395:     private static Result runTypeInferenceInternal(
396:             TypeInference typeInference,
397:             CallContext callContext,
398:             @Nullable SurroundingInfo surroundingInfo) {
399:         try {
400:             validateArgumentCount(
401:                     typeInference.getInputTypeStrategy().getArgumentCount(),
402:                     callContext.getArgumentDataTypes().size(),
403:                     true);
404:         } catch (ValidationException e) {
405:             throw createInvalidInputException(typeInference, callContext, e);
406:         }
407: 
408:         final CallContext adaptedCallContext;
409:         try {
410:             // use information of surrounding call to determine output type of this call
411:             final DataType outputType;
412:             if (surroundingInfo != null) {
413:                 outputType =
414:                         surroundingInfo
415:                                 .inferOutputType(callContext.getDataTypeFactory())
416:                                 .orElse(null);
