201:     /**
202:      * Private constructor that creates a re-configured copy of the state backend.
203:      *
204:      * @param original The state backend to re-configure.
205:      * @param config The configuration.
206:      * @param classLoader The class loader.
207:      */
208:     private ForStStateBackend(
209:             ForStStateBackend original, ReadableConfig config, ClassLoader classLoader) {
210:         this.memoryConfiguration =
211:                 ForStMemoryConfiguration.fromOtherAndConfiguration(
212:                         original.memoryConfiguration, config);
213:         this.memoryConfiguration.validate();
214: 
215:         this.remoteShareWithCheckpoint = false;
216:         if (original.remoteForStDirectory != null) {
217:             this.remoteForStDirectory = original.remoteForStDirectory;
218:         } else {
219:             String remoteDirStr = config.get(ForStOptions.PRIMARY_DIRECTORY);
220:             if (PRIMARY_SHORTCUT_CHECKPOINT.equals(remoteDirStr)) {
221:                 this.remoteForStDirectory = null;
222:                 this.remoteShareWithCheckpoint = true;
223:             } else {
224:                 this.remoteForStDirectory = remoteDirStr == null ? null : new Path(remoteDirStr);
225:             }
226:         }
227: 
228:         this.priorityQueueConfig =
229:                 ForStPriorityQueueConfig.fromOtherAndConfiguration(
230:                         original.priorityQueueConfig, config);
231: 
232:         // configure local directories
233:         if (original.localForStDirectories != null) {
234:             this.localForStDirectories = original.localForStDirectories;
235:         } else {
236:             final String forStLocalPaths = config.get(ForStOptions.LOCAL_DIRECTORIES);
237:             if (forStLocalPaths != null) {
238:                 String[] directories = forStLocalPaths.split(",|" + File.pathSeparator);
239: 
240:                 try {
241:                     setLocalDbStoragePaths(directories);
242:                 } catch (IllegalArgumentException e) {
243:                     throw new IllegalConfigurationException(
244:                             "Invalid configuration for ForSt state "
245:                                     + "backend's local storage directories: "
246:                                     + e.getMessage(),
247:                             e);
248:                 }
249:             }
250:         }
251: 
252:         // configure metric options
253:         this.nativeMetricOptions = ForStNativeMetricOptions.fromConfig(config);
254: 
255:         // configurable options
256:         this.configurableOptions = mergeConfigurableOptions(original.configurableOptions, config);
257: 
258:         // configure ForSt options factory
259:         try {
260:             forStOptionsFactory =
261:                     configureOptionsFactory(
262:                             original.forStOptionsFactory,
263:                             config.get(ForStOptions.OPTIONS_FACTORY),
264:                             config,
265:                             classLoader);
266:         } catch (DynamicCodeLoadingException e) {
267:             throw new FlinkRuntimeException(e);
268:         }
269: 
270:         // configure latency tracking
271:         latencyTrackingConfigBuilder = original.latencyTrackingConfigBuilder.configure(config);
272: 
273:         this.forStMemoryFactory = original.forStMemoryFactory;
274: 
275:         // configure overlap fraction threshold
276:         overlapFractionThreshold =
277:                 original.overlapFractionThreshold == UNDEFINED_OVERLAP_FRACTION_THRESHOLD
278:                         ? config.get(RESTORE_OVERLAP_FRACTION_THRESHOLD)
279:                         : original.overlapFractionThreshold;
280: 
281:         checkArgument(
282:                 overlapFractionThreshold >= 0 && this.overlapFractionThreshold <= 1,
283:                 "Overlap fraction threshold of restoring should be between 0 and 1");
284: 
285:         useIngestDbRestoreMode =
286:                 TernaryBoolean.mergeTernaryBooleanWithConfig(
287:                         original.useIngestDbRestoreMode, USE_INGEST_DB_RESTORE_MODE, config);
288: 
289:         rescalingUseDeleteFilesInRange =
290:                 TernaryBoolean.mergeTernaryBooleanWithConfig(
291:                         original.rescalingUseDeleteFilesInRange,
292:                         USE_DELETE_FILES_IN_RANGE_DURING_RESCALING,
293:                         config);
294: 
295:         if (config.getOptional(RESTORE_MODE).isPresent()) {
296:             recoveryClaimMode = config.get(RESTORE_MODE);
297:         }
298:     }
