219: /**
220:  * These are Java and Scala common operations that can be used to construct an {@link Expression}
221:  * AST for expression operations.
222:  *
223:  * @param <InType> The accepted type of input expressions, it is {@code Expression} for Scala and
224:  *     {@code Object} for Java. Generally the expression DSL works on expressions, the reason why
225:  *     Java accepts Object is to remove cumbersome call to {@code lit()} for literals. Scala
226:  *     alleviates this problem via implicit conversions.
227:  * @param <OutType> The produced type of the DSL. It is {@code ApiExpression} for Java and {@code
228:  *     Expression} for Scala. In Scala the infix operations are included via implicit conversions.
229:  *     In Java we introduced a wrapper that enables the operations without pulling them through the
230:  *     whole stack.
231:  */
232: @PublicEvolving
233: public abstract class BaseExpressions<InType, OutType> {
234:     protected abstract Expression toExpr();
235: 
236:     protected abstract OutType toApiSpecificExpression(Expression expression);
237: 
238:     /**
239:      * Specifies a name for an expression i.e. a field.
240:      *
241:      * @param name name for one field
242:      * @param extraNames additional names if the expression expands to multiple fields
243:      */
244:     public OutType as(String name, String... extraNames) {
245:         return toApiSpecificExpression(
246:                 ApiExpressionUtils.unresolvedCall(
247:                         BuiltInFunctionDefinitions.AS,
248:                         Stream.concat(
249:                                         Stream.of(toExpr(), ApiExpressionUtils.valueLiteral(name)),
250:                                         Stream.of(extraNames).map(ApiExpressionUtils::valueLiteral))
251:                                 .toArray(Expression[]::new)));
252:     }
