323:     private static void initializeBoundedBlockingPartitions(
324:             ResultSubpartition[] subpartitions,
325:             BoundedBlockingResultPartition parent,
326:             BoundedBlockingSubpartitionType blockingSubpartitionType,
327:             int networkBufferSize,
328:             FileChannelManager channelManager,
329:             boolean sslEnabled) {
330:         int i = 0;
331:         try {
332:             for (i = 0; i < subpartitions.length; i++) {
333:                 final File spillFile = channelManager.createChannel().getPathFile();
334:                 subpartitions[i] =
335:                         blockingSubpartitionType.create(
336:                                 i, parent, spillFile, networkBufferSize, sslEnabled);
337:             }
338:         } catch (IOException e) {
339:             // undo all the work so that a failed constructor does not leave any resources
340:             // in need of disposal
341:             releasePartitionsQuietly(subpartitions, i);
342: 
343:             // this is not good, we should not be forced to wrap this in a runtime exception.
344:             // the fact that the ResultPartition and Task constructor (which calls this) do not
345:             // tolerate any exceptions
346:             // is incompatible with eager initialization of resources (RAII).
347:             throw new FlinkRuntimeException(e);
348:         }
349:     }
