358:     /** Return whether this result partition need overdraft buffer. */
359:     private static boolean isOverdraftBufferNeeded(ResultPartitionType resultPartitionType) {
360:         // Only pipelined / pipelined-bounded partition needs overdraft buffer. More
361:         // specifically, there is no reason to request more buffers for non-pipelined (i.e.
362:         // batch) shuffle. The reasons are as follows:
363:         // 1. For BoundedBlockingShuffle, each full buffer will be directly released.
364:         // 2. For SortMergeShuffle, the maximum capacity of buffer pool is 4 * numSubpartitions. It
365:         // is efficient enough to spill this part of memory to disk.
366:         // 3. For Hybrid Shuffle, the buffer pool is unbounded. If it can't get a normal buffer, it
367:         // also can't get an overdraft buffer.
368:         return resultPartitionType.isPipelinedOrPipelinedBoundedResultPartition();
369:     }
370: 
371:     /**
372:      * The minimum pool size should be <code>numberOfSubpartitions + 1</code> for two
373:      * considerations:
374:      *
375:      * <p>1. StreamTask can only process input if there is at-least one available buffer on output
376:      * side, so it might cause stuck problem if the minimum pool size is exactly equal to the number
377:      * of subpartitions, because every subpartition might maintain a partial unfilled buffer.
378:      *
379:      * <p>2. Increases one more buffer for every output LocalBufferPool to avoid performance
380:      * regression if processing input is based on at-least one buffer available on output side.
381:      */
382:     @VisibleForTesting
383:     SupplierWithException<BufferPool, IOException> createBufferPoolFactory(
384:             int numberOfSubpartitions, ResultPartitionType type) {
385:         return () -> {
386:             Tuple3<Integer, Integer, Integer> tuple =
387:                     NettyShuffleUtils.getMinMaxNetworkBuffersPerResultPartition(
388:                             configuredNetworkBuffersPerChannel,
389:                             floatingNetworkBuffersPerGate,
390:                             sortShuffleMinParallelism,
391:                             sortShuffleMinBuffers,
392:                             numberOfSubpartitions,
393:                             tieredStorage.isPresent(),
394:                             tieredStorage
395:                                     .map(ResultPartitionFactory::getNumTotalGuaranteedBuffers)
396:                                     .orElse(0),
397:                             type);
398: 
399:             return bufferPoolFactory.createBufferPool(
400:                     tuple.f0,
401:                     tuple.f1,
402:                     tuple.f2,
403:                     numberOfSubpartitions,
404:                     maxBuffersPerChannel,
405:                     isOverdraftBufferNeeded(type) ? maxOverdraftBuffersPerGate : 0);
406:         };
407:     }
408: 
409:     static BoundedBlockingSubpartitionType getBoundedBlockingType() {
410:         switch (ProcessorArchitecture.getMemoryAddressSize()) {
411:             case _64_BIT:
412:                 return BoundedBlockingSubpartitionType.FILE_MMAP;
413:             case _32_BIT:
414:                 return BoundedBlockingSubpartitionType.FILE;
415:             default:
416:                 LOG.warn("Cannot determine memory architecture. Using pure file-based shuffle.");
417:                 return BoundedBlockingSubpartitionType.FILE;
418:         }
419:     }
420: 
421:     private static int getNumTotalGuaranteedBuffers(
422:             TieredResultPartitionFactory resultPartitionFactory) {
423:         return resultPartitionFactory.getTieredStorageConfiguration().getTierFactories().stream()
424:                 .map(TierFactory::getProducerAgentMemorySpec)
425:                 .map(TieredStorageMemorySpec::getNumGuaranteedBuffers)
426:                 .mapToInt(Integer::intValue)
427:                 .sum();
428:     }
