796:         try (BufferBuilder bufferBuilder = getFinishedBufferBuilder(resultPartition, 6);
797:                 BufferConsumer bufferConsumer = bufferBuilder.createBufferConsumerFromBeginning()) {
798:             resultPartition.addRecovered(0, bufferConsumer.copy());
799:             assertThat(resultPartition.getSizeOfQueuedBuffersUnsafe()).isEqualTo(6);
800: 
801:             resultPartition.addRecovered(1, bufferConsumer.copy());
802:             assertThat(resultPartition.getSizeOfQueuedBuffersUnsafe()).isEqualTo(12);
803:         }
804: 
805:         // Emit the EndOfChannelStateEvent for all channel
806:         resultPartition.finishReadRecoveredState(true);
807:         assertThat(resultPartition.getSizeOfQueuedBuffersUnsafe()).isEqualTo(20);
808: 
809:         // Emit the record less than buffer size.
810:         resultPartition.emitRecord(ByteBuffer.allocate(3), 0);
