812: 
813:         resultPartition.emitRecord(ByteBuffer.allocate(3), 1);
814:         assertThat(resultPartition.getSizeOfQueuedBuffersUnsafe()).isEqualTo(26);
815: 
816:         // Emit the record the equal to buffer size.
817:         resultPartition.emitRecord(ByteBuffer.allocate(10), 0);
