819: 
820:         resultPartition.emitRecord(ByteBuffer.allocate(10), 1);
821:         assertThat(resultPartition.getSizeOfQueuedBuffersUnsafe()).isEqualTo(46);
822: 
823:         // Broadcast event.
824:         resultPartition.broadcastEvent(EndOfPartitionEvent.INSTANCE, false);
825:         assertThat(resultPartition.getSizeOfQueuedBuffersUnsafe()).isEqualTo(54);
826: 
827:         // Emit one more record to the one subpartition.
828:         resultPartition.emitRecord(ByteBuffer.allocate(5), 0);
829:         assertThat(resultPartition.getSizeOfQueuedBuffersUnsafe()).isEqualTo(59);
830: 
831:         // Broadcast record.
832:         resultPartition.broadcastRecord(ByteBuffer.allocate(7));
833:         assertThat(resultPartition.getSizeOfQueuedBuffersUnsafe()).isEqualTo(73);
834: 
835:         // Poll the recovered state.
836:         assertThat(subpartition0.pollBuffer().buffer().getSize()).isEqualTo(6);
837:         assertThat(resultPartition.getSizeOfQueuedBuffersUnsafe()).isEqualTo(67);
838: 
839:         assertThat(subpartition1.pollBuffer().buffer().getSize()).isEqualTo(6);
840:         assertThat(resultPartition.getSizeOfQueuedBuffersUnsafe()).isEqualTo(61);
841: 
842:         // Poll the EndOfChannelStateEvent and resume the consumption.
843:         assertThat(subpartition0.pollBuffer().buffer().getSize()).isEqualTo(4);
844:         assertThat(resultPartition.getSizeOfQueuedBuffersUnsafe()).isEqualTo(57);
845: 
