127:         this.maxRequiredBuffersPerGate = networkConfig.maxRequiredBuffersPerGate();
128:         this.configuredNetworkBuffersPerChannel =
129:                 NettyShuffleUtils.getNetworkBuffersPerInputChannel(
130:                         networkConfig.networkBuffersPerChannel());
131:         this.floatingNetworkBuffersPerGate = networkConfig.floatingNetworkBuffersPerGate();
132:         this.batchShuffleCompressionEnabled = networkConfig.isBatchShuffleCompressionEnabled();
133:         this.compressionCodec = networkConfig.getCompressionCodec();
