219:     private BufferDebloater maybeCreateBufferDebloater(
220:             String owningTaskName, int gateIndex, MetricGroup inputGroup) {
221:         if (debloatConfiguration.isEnabled()) {
222:             final BufferDebloater bufferDebloater =
223:                     new BufferDebloater(
224:                             owningTaskName,
225:                             gateIndex,
226:                             debloatConfiguration.getTargetTotalBufferSize().toMillis(),
227:                             debloatConfiguration.getMaxBufferSize(),
228:                             debloatConfiguration.getMinBufferSize(),
229:                             debloatConfiguration.getBufferDebloatThresholdPercentages(),
230:                             debloatConfiguration.getNumberOfSamples());
231:             inputGroup.gauge(
232:                     MetricNames.ESTIMATED_TIME_TO_CONSUME_BUFFERS,
233:                     () -> bufferDebloater.getLastEstimatedTimeToConsumeBuffers().toMillis());
234:             inputGroup.gauge(MetricNames.DEBLOATED_BUFFER_SIZE, bufferDebloater::getLastBufferSize);
235:             return bufferDebloater;
236:         }
237: 
238:         return null;
239:     }
