465:     /** A {@link Committer} that always re-commits the committables data it received. */
466:     static class RetryOnceCommitter extends DefaultCommitter {
467: 
468:         private final Set<String> seen = new LinkedHashSet<>();
469: 
470:         @Override
471:         public void commit(Collection<CommitRequest<String>> committables) {
472:             committables.forEach(
473:                     c -> {
474:                         if (seen.remove(c.getCommittable())) {
475:                             checkNotNull(committedData);
476:                             committedData.add(c);
477:                         } else {
478:                             seen.add(c.getCommittable());
479:                             c.retryLater();
480:                         }
481:                     });
482:         }
483:     }
