419:     private Optional<REPORTER> loadReporter(
420:             final String reporterName,
421:             final Configuration reporterConfig,
422:             final Map<String, REPORTER_FACTORY> reporterFactories) {
423: 
424:         final String factoryClassName = reporterConfig.get(reporterSetupInfo.factoryClassConfig);
425: 
426:         if (factoryClassName != null) {
427:             return loadViaFactory(
428:                     factoryClassName, reporterName, reporterConfig, reporterFactories);
429:         }
