275:     protected void serializeSubtaskState(OperatorSubtaskState subtaskState, DataOutputStream dos)
276:             throws IOException {
277:         serializeSingleton(
278:                 subtaskState.getManagedOperatorState(), dos, this::serializeOperatorStateHandle);
279:         serializeSingleton(
280:                 subtaskState.getRawOperatorState(), dos, this::serializeOperatorStateHandle);
281:         serializeKeyedStateCol(subtaskState.getManagedKeyedState(), dos);
282:         serializeKeyedStateCol(subtaskState.getRawKeyedState(), dos);
283:     }
