325:     @VisibleForTesting
326:     static void serializeKeyedStateHandle(KeyedStateHandle stateHandle, DataOutputStream dos)
327:             throws IOException {
328:         if (stateHandle == null) {
329:             dos.writeByte(NULL_HANDLE);
330:         } else if (stateHandle instanceof KeyGroupsStateHandle) {
331:             KeyGroupsStateHandle keyGroupsStateHandle = (KeyGroupsStateHandle) stateHandle;
332: 
333:             if (stateHandle instanceof KeyGroupsSavepointStateHandle) {
334:                 dos.writeByte(SAVEPOINT_KEY_GROUPS_HANDLE);
335:             } else {
336:                 dos.writeByte(KEY_GROUPS_HANDLE_V2);
337:             }
338:             dos.writeInt(keyGroupsStateHandle.getKeyGroupRange().getStartKeyGroup());
339:             dos.writeInt(keyGroupsStateHandle.getKeyGroupRange().getNumberOfKeyGroups());
340:             for (int keyGroup : keyGroupsStateHandle.getKeyGroupRange()) {
341:                 dos.writeLong(keyGroupsStateHandle.getOffsetForKeyGroup(keyGroup));
342:             }
343:             serializeStreamStateHandle(keyGroupsStateHandle.getDelegateStateHandle(), dos);
344: 
345:             // savepoint state handle would not need to persist state handle id out.
346:             if (!(stateHandle instanceof KeyGroupsSavepointStateHandle)) {
347:                 writeStateHandleId(stateHandle, dos);
348:             }
349:         } else if (stateHandle instanceof IncrementalRemoteKeyedStateHandle) {
350:             IncrementalRemoteKeyedStateHandle incrementalKeyedStateHandle =
351:                     (IncrementalRemoteKeyedStateHandle) stateHandle;
352: 
353:             dos.writeByte(INCREMENTAL_KEY_GROUPS_HANDLE_V2);
354: 
355:             dos.writeLong(incrementalKeyedStateHandle.getCheckpointId());
356:             dos.writeUTF(String.valueOf(incrementalKeyedStateHandle.getBackendIdentifier()));
357:             dos.writeInt(incrementalKeyedStateHandle.getKeyGroupRange().getStartKeyGroup());
358:             dos.writeInt(incrementalKeyedStateHandle.getKeyGroupRange().getNumberOfKeyGroups());
359:             dos.writeLong(incrementalKeyedStateHandle.getCheckpointedSize());
360: 
361:             serializeStreamStateHandle(incrementalKeyedStateHandle.getMetaDataStateHandle(), dos);
362: 
363:             serializeHandleAndLocalPathList(incrementalKeyedStateHandle.getSharedState(), dos);
364:             serializeHandleAndLocalPathList(incrementalKeyedStateHandle.getPrivateState(), dos);
365: 
366:             writeStateHandleId(incrementalKeyedStateHandle, dos);
367:         } else if (stateHandle instanceof ChangelogStateBackendHandle) {
368:             ChangelogStateBackendHandle handle = (ChangelogStateBackendHandle) stateHandle;
369: 
370:             dos.writeByte(CHANGELOG_HANDLE_V2);
371:             dos.writeInt(handle.getKeyGroupRange().getStartKeyGroup());
372:             dos.writeInt(handle.getKeyGroupRange().getNumberOfKeyGroups());
373: 
374:             dos.writeLong(handle.getCheckpointedSize());
375: 
376:             dos.writeInt(handle.getMaterializedStateHandles().size());
377:             for (KeyedStateHandle keyedStateHandle : handle.getMaterializedStateHandles()) {
378:                 serializeKeyedStateHandle(keyedStateHandle, dos);
379:             }
380: 
381:             dos.writeInt(handle.getNonMaterializedStateHandles().size());
382:             for (KeyedStateHandle k : handle.getNonMaterializedStateHandles()) {
383:                 serializeKeyedStateHandle(k, dos);
384:             }
385: 
386:             dos.writeLong(handle.getMaterializationID());
387:             dos.writeLong(handle.getCheckpointId());
388:             writeStateHandleId(handle, dos);
389: 
390:         } else if (stateHandle instanceof InMemoryChangelogStateHandle) {
391:             InMemoryChangelogStateHandle handle = (InMemoryChangelogStateHandle) stateHandle;
392:             dos.writeByte(CHANGELOG_BYTE_INCREMENT_HANDLE);
393:             dos.writeInt(handle.getKeyGroupRange().getStartKeyGroup());
394:             dos.writeInt(handle.getKeyGroupRange().getNumberOfKeyGroups());
395:             dos.writeLong(handle.getFrom());
396:             dos.writeLong(handle.getTo());
397:             dos.writeInt(handle.getChanges().size());
398:             for (StateChange change : handle.getChanges()) {
399:                 dos.writeInt(change.getKeyGroup());
400:                 dos.writeInt(change.getChange().length);
401:                 dos.write(change.getChange());
402:             }
403:             writeStateHandleId(handle, dos);
404:         } else if (stateHandle instanceof ChangelogStateHandleStreamImpl) {
405:             ChangelogStateHandleStreamImpl handle = (ChangelogStateHandleStreamImpl) stateHandle;
406:             dos.writeByte(CHANGELOG_FILE_INCREMENT_HANDLE_V2);
407:             dos.writeInt(handle.getKeyGroupRange().getStartKeyGroup());
408:             dos.writeInt(handle.getKeyGroupRange().getNumberOfKeyGroups());
409:             dos.writeInt(handle.getHandlesAndOffsets().size());
410:             for (Tuple2<StreamStateHandle, Long> streamHandleAndOffset :
411:                     handle.getHandlesAndOffsets()) {
412:                 dos.writeLong(streamHandleAndOffset.f1);
413:                 serializeStreamStateHandle(streamHandleAndOffset.f0, dos);
414:             }
415:             dos.writeLong(handle.getStateSize());
416:             dos.writeLong(handle.getCheckpointedSize());
417:             writeStateHandleId(handle, dos);
418:             dos.writeUTF(handle.getStorageIdentifier());
419:         } else {
420:             throw new IllegalStateException(
421:                     "Unknown KeyedStateHandle type: " + stateHandle.getClass());
422:         }
423:     }
