291:     protected OperatorSubtaskState deserializeSubtaskState(
292:             DataInputStream dis, @Nullable DeserializationContext context) throws IOException {
293: 
294:         final OperatorSubtaskState.Builder state = OperatorSubtaskState.builder();
295: 
296:         final boolean hasManagedOperatorState = dis.readInt() != 0;
297:         if (hasManagedOperatorState) {
298:             state.setManagedOperatorState(deserializeOperatorStateHandle(dis, context));
299:         }
300: 
301:         final boolean hasRawOperatorState = dis.readInt() != 0;
302:         if (hasRawOperatorState) {
303:             state.setRawOperatorState(deserializeOperatorStateHandle(dis, context));
304:         }
305: 
306:         final KeyedStateHandle managedKeyedState = deserializeKeyedStateHandle(dis, context);
307:         if (managedKeyedState != null) {
308:             state.setManagedKeyedState(managedKeyedState);
309:         }
310:         final KeyedStateHandle rawKeyedState = deserializeKeyedStateHandle(dis, context);
311:         if (rawKeyedState != null) {
312:             state.setRawKeyedState(rawKeyedState);
313:         }
314: 
315:         state.setInputChannelState(deserializeInputChannelStateHandle(dis, context));
316:         state.setResultSubpartitionState(deserializeResultSubpartitionStateHandle(dis, context));
317: 
318:         return state.build();
319:     }
