425:     private static void writeStateHandleId(KeyedStateHandle keyedStateHandle, DataOutputStream dos)
426:             throws IOException {
427:         dos.writeUTF(keyedStateHandle.getStateHandleId().getKeyString());
428:     }
429: 
430:     @VisibleForTesting
431:     @Nullable
432:     static KeyedStateHandle deserializeKeyedStateHandle(
433:             DataInputStream dis, @Nullable DeserializationContext context) throws IOException {
434: 
435:         final int type = dis.readByte();
436:         if (NULL_HANDLE == type) {
437: 
438:             return null;
439:         } else if (KEY_GROUPS_HANDLE == type
440:                 || KEY_GROUPS_HANDLE_V2 == type
441:                 || SAVEPOINT_KEY_GROUPS_HANDLE == type) {
442:             int startKeyGroup = dis.readInt();
443:             int numKeyGroups = dis.readInt();
444:             KeyGroupRange keyGroupRange =
445:                     KeyGroupRange.of(startKeyGroup, startKeyGroup + numKeyGroups - 1);
446:             long[] offsets = new long[numKeyGroups];
447:             for (int i = 0; i < numKeyGroups; ++i) {
448:                 offsets[i] = dis.readLong();
449:             }
450:             KeyGroupRangeOffsets keyGroupRangeOffsets =
451:                     new KeyGroupRangeOffsets(keyGroupRange, offsets);
452:             StreamStateHandle stateHandle = deserializeStreamStateHandle(dis, context);
453:             if (SAVEPOINT_KEY_GROUPS_HANDLE == type) {
454:                 return new KeyGroupsSavepointStateHandle(keyGroupRangeOffsets, stateHandle);
455:             } else {
456:                 StateHandleID stateHandleID =
457:                         KEY_GROUPS_HANDLE_V2 == type
458:                                 ? new StateHandleID(dis.readUTF())
459:                                 : StateHandleID.randomStateHandleId();
460:                 return KeyGroupsStateHandle.restore(
461:                         keyGroupRangeOffsets, stateHandle, stateHandleID);
462:             }
463:         } else if (INCREMENTAL_KEY_GROUPS_HANDLE == type
464:                 || INCREMENTAL_KEY_GROUPS_HANDLE_V2 == type) {
465:             return deserializeIncrementalStateHandle(dis, context, type);
466:         } else if (CHANGELOG_HANDLE == type || CHANGELOG_HANDLE_V2 == type) {
467: 
468:             int startKeyGroup = dis.readInt();
469:             int numKeyGroups = dis.readInt();
470:             KeyGroupRange keyGroupRange =
471:                     KeyGroupRange.of(startKeyGroup, startKeyGroup + numKeyGroups - 1);
472:             long checkpointedSize = dis.readLong();
473: 
474:             int baseSize = dis.readInt();
475:             List<KeyedStateHandle> base = new ArrayList<>(baseSize);
476:             for (int i = 0; i < baseSize; i++) {
477:                 KeyedStateHandle handle = deserializeKeyedStateHandle(dis, context);
478:                 if (handle != null) {
479:                     base.add(handle);
480:                 } else {
481:                     LOG.warn(
482:                             "Unexpected null keyed state handle of materialized part when deserializing changelog state-backend handle");
483:                 }
484:             }
485:             int deltaSize = dis.readInt();
486:             List<ChangelogStateHandle> delta = new ArrayList<>(deltaSize);
487:             for (int i = 0; i < deltaSize; i++) {
488:                 delta.add((ChangelogStateHandle) deserializeKeyedStateHandle(dis, context));
489:             }
490: 
491:             long materializationID = dis.readLong();
492:             long checkpointId = CHANGELOG_HANDLE_V2 == type ? dis.readLong() : materializationID;
493:             StateHandleID stateHandleId = new StateHandleID(dis.readUTF());
494:             return ChangelogStateBackendHandleImpl.restore(
495:                     base,
496:                     delta,
497:                     keyGroupRange,
498:                     checkpointId,
499:                     materializationID,
500:                     checkpointedSize,
501:                     stateHandleId);
502: 
503:         } else if (CHANGELOG_BYTE_INCREMENT_HANDLE == type) {
504:             int start = dis.readInt();
505:             int numKeyGroups = dis.readInt();
506:             KeyGroupRange keyGroupRange = KeyGroupRange.of(start, start + numKeyGroups - 1);
507:             long from = dis.readLong();
508:             long to = dis.readLong();
509:             int size = dis.readInt();
510:             List<StateChange> changes = new ArrayList<>(size);
511:             for (int i = 0; i < size; i++) {
512:                 int keyGroup = dis.readInt();
513:                 int bytesSize = dis.readInt();
514:                 byte[] bytes = new byte[bytesSize];
515:                 IOUtils.readFully(dis, bytes, 0, bytesSize);
516:                 StateChange stateChange =
517:                         keyGroup == META_KEY_GROUP
518:                                 ? StateChange.ofMetadataChange(bytes)
519:                                 : StateChange.ofDataChange(keyGroup, bytes);
520:                 changes.add(stateChange);
521:             }
522:             StateHandleID stateHandleId = new StateHandleID(dis.readUTF());
523:             return InMemoryChangelogStateHandle.restore(
524:                     changes,
525:                     SequenceNumber.of(from),
526:                     SequenceNumber.of(to),
527:                     keyGroupRange,
528:                     stateHandleId);
529: 
530:         } else if (CHANGELOG_FILE_INCREMENT_HANDLE == type
531:                 || CHANGELOG_FILE_INCREMENT_HANDLE_V2 == type) {
532:             int start = dis.readInt();
533:             int numKeyGroups = dis.readInt();
534:             KeyGroupRange keyGroupRange = KeyGroupRange.of(start, start + numKeyGroups - 1);
535:             int numHandles = dis.readInt();
536:             List<Tuple2<StreamStateHandle, Long>> streamHandleAndOffset =
537:                     new ArrayList<>(numHandles);
538:             for (int i = 0; i < numHandles; i++) {
539:                 long o = dis.readLong();
540:                 StreamStateHandle h = deserializeStreamStateHandle(dis, context);
541:                 streamHandleAndOffset.add(Tuple2.of(h, o));
542:             }
543:             long size = dis.readLong();
544:             long checkpointedSize = dis.readLong();
545:             StateHandleID stateHandleId = new StateHandleID(dis.readUTF());
546:             String storageIdentifier =
547:                     CHANGELOG_FILE_INCREMENT_HANDLE_V2 == type ? dis.readUTF() : "filesystem";
548:             return ChangelogStateHandleStreamImpl.restore(
549:                     streamHandleAndOffset,
550:                     keyGroupRange,
551:                     size,
552:                     checkpointedSize,
553:                     storageIdentifier,
554:                     stateHandleId);
555:         } else {
556:             throw new IllegalStateException("Reading invalid KeyedStateHandle, type: " + type);
557:         }
558:     }
