599:     void serializeOperatorStateHandle(OperatorStateHandle stateHandle, DataOutputStream dos)
600:             throws IOException {
601:         if (stateHandle != null) {
602:             dos.writeByte(
603:                     stateHandle instanceof FileMergingOperatorStreamStateHandle
604:                             ? SEGMENT_PARTITIONABLE_OPERATOR_STATE_HANDLE
605:                             : PARTITIONABLE_OPERATOR_STATE_HANDLE);
606:             Map<String, OperatorStateHandle.StateMetaInfo> partitionOffsetsMap =
607:                     stateHandle.getStateNameToPartitionOffsets();
608:             dos.writeInt(partitionOffsetsMap.size());
609:             for (Map.Entry<String, OperatorStateHandle.StateMetaInfo> entry :
610:                     partitionOffsetsMap.entrySet()) {
611:                 dos.writeUTF(entry.getKey());
612: 
613:                 OperatorStateHandle.StateMetaInfo stateMetaInfo = entry.getValue();
614: 
615:                 int mode = stateMetaInfo.getDistributionMode().ordinal();
616:                 dos.writeByte(mode);
617: 
618:                 long[] offsets = stateMetaInfo.getOffsets();
619:                 dos.writeInt(offsets.length);
620:                 for (long offset : offsets) {
621:                     dos.writeLong(offset);
622:                 }
623:             }
624:             if (stateHandle instanceof FileMergingOperatorStreamStateHandle) {
625:                 dos.writeUTF(
626:                         ((FileMergingOperatorStreamStateHandle) stateHandle)
627:                                 .getTaskOwnedDirHandle()
628:                                 .getDirectory()
629:                                 .toString());
630:                 dos.writeUTF(
631:                         ((FileMergingOperatorStreamStateHandle) stateHandle)
632:                                 .getSharedDirHandle()
633:                                 .getDirectory()
634:                                 .toString());
635:                 dos.writeBoolean(stateHandle instanceof EmptyFileMergingOperatorStreamStateHandle);
636:             }
637:             serializeStreamStateHandle(stateHandle.getDelegateStateHandle(), dos);
638:         } else {
639:             dos.writeByte(NULL_HANDLE);
640:         }
641:     }
642: 
643:     OperatorStateHandle deserializeOperatorStateHandle(
644:             DataInputStream dis, @Nullable DeserializationContext context) throws IOException {
645: 
646:         final int type = dis.readByte();
647:         if (NULL_HANDLE == type) {
648:             return null;
649:         } else if (PARTITIONABLE_OPERATOR_STATE_HANDLE == type
650:                 || SEGMENT_PARTITIONABLE_OPERATOR_STATE_HANDLE == type) {
651:             int mapSize = dis.readInt();
652:             Map<String, OperatorStateHandle.StateMetaInfo> offsetsMap =
653:                     CollectionUtil.newHashMapWithExpectedSize(mapSize);
654:             for (int i = 0; i < mapSize; ++i) {
655:                 String key = dis.readUTF();
656: 
657:                 int modeOrdinal = dis.readByte();
658:                 OperatorStateHandle.Mode mode = OperatorStateHandle.Mode.values()[modeOrdinal];
659: 
660:                 long[] offsets = new long[dis.readInt()];
661:                 for (int j = 0; j < offsets.length; ++j) {
662:                     offsets[j] = dis.readLong();
663:                 }
664: 
665:                 OperatorStateHandle.StateMetaInfo metaInfo =
666:                         new OperatorStateHandle.StateMetaInfo(offsets, mode);
667:                 offsetsMap.put(key, metaInfo);
668:             }
669:             if (SEGMENT_PARTITIONABLE_OPERATOR_STATE_HANDLE == type) {
670:                 String taskOwnedDirPathStr = dis.readUTF();
671:                 String sharedDirPathStr = dis.readUTF();
672:                 boolean isEmpty = dis.readBoolean();
673:                 StreamStateHandle stateHandle = deserializeStreamStateHandle(dis, context);
674:                 Preconditions.checkArgument(stateHandle instanceof SegmentFileStateHandle);
675:                 return isEmpty
676:                         ? new EmptyFileMergingOperatorStreamStateHandle(
677:                                 DirectoryStreamStateHandle.of(new Path(taskOwnedDirPathStr)),
678:                                 DirectoryStreamStateHandle.of(new Path(sharedDirPathStr)),
679:                                 offsetsMap,
680:                                 stateHandle)
681:                         : new FileMergingOperatorStreamStateHandle(
682:                                 DirectoryStreamStateHandle.of(new Path(taskOwnedDirPathStr)),
683:                                 DirectoryStreamStateHandle.of(new Path(sharedDirPathStr)),
684:                                 offsetsMap,
685:                                 stateHandle);
686:             } else {
687:                 StreamStateHandle stateHandle = deserializeStreamStateHandle(dis, context);
688:                 return new OperatorStreamStateHandle(offsetsMap, stateHandle);
689:             }
690:         } else {
691:             throw new IllegalStateException("Reading invalid OperatorStateHandle, type: " + type);
692:         }
693:     }
