720:     static void serializeStreamStateHandle(StreamStateHandle stateHandle, DataOutputStream dos)
721:             throws IOException {
722:         if (stateHandle == null) {
723:             dos.writeByte(NULL_HANDLE);
724: 
725:         } else if (stateHandle instanceof RelativeFileStateHandle) {
726:             dos.writeByte(RELATIVE_STREAM_STATE_HANDLE);
727:             RelativeFileStateHandle relativeFileStateHandle = (RelativeFileStateHandle) stateHandle;
728:             dos.writeUTF(relativeFileStateHandle.getRelativePath());
729:             dos.writeLong(relativeFileStateHandle.getStateSize());
730:         } else if (stateHandle instanceof SegmentFileStateHandle) {
731:             if (stateHandle instanceof EmptySegmentFileStateHandle) {
732:                 dos.writeByte(EMPTY_SEGMENT_FILE_HANDLE);
733:             } else {
734:                 dos.writeByte(SEGMENT_FILE_HANDLE);
735:                 SegmentFileStateHandle segmentFileStateHandle =
736:                         (SegmentFileStateHandle) stateHandle;
737:                 dos.writeLong(segmentFileStateHandle.getStartPos());
738:                 dos.writeLong(segmentFileStateHandle.getStateSize());
739:                 dos.writeInt(segmentFileStateHandle.getScope().ordinal());
740:                 dos.writeUTF(segmentFileStateHandle.getFilePath().toString());
741:                 dos.writeUTF(segmentFileStateHandle.getLogicalFileId().getKeyString());
742:             }
743:         } else if (stateHandle instanceof FileStateHandle) {
744:             dos.writeByte(FILE_STREAM_STATE_HANDLE);
745:             FileStateHandle fileStateHandle = (FileStateHandle) stateHandle;
746:             dos.writeLong(stateHandle.getStateSize());
747:             dos.writeUTF(fileStateHandle.getFilePath().toString());
748: 
749:         } else if (stateHandle instanceof ByteStreamStateHandle) {
750:             dos.writeByte(BYTE_STREAM_STATE_HANDLE);
751:             ByteStreamStateHandle byteStreamStateHandle = (ByteStreamStateHandle) stateHandle;
752:             dos.writeUTF(byteStreamStateHandle.getHandleName());
753:             byte[] internalData = byteStreamStateHandle.getData();
754:             dos.writeInt(internalData.length);
755:             dos.write(byteStreamStateHandle.getData());
756:         } else if (stateHandle instanceof KeyGroupsStateHandle) {
757:             KeyGroupsStateHandle keyGroupsStateHandle = (KeyGroupsStateHandle) stateHandle;
758:             dos.writeByte(KEY_GROUPS_HANDLE);
759:             dos.writeInt(keyGroupsStateHandle.getKeyGroupRange().getStartKeyGroup());
760:             dos.writeInt(keyGroupsStateHandle.getKeyGroupRange().getNumberOfKeyGroups());
761:             for (int keyGroup : keyGroupsStateHandle.getKeyGroupRange()) {
762:                 dos.writeLong(keyGroupsStateHandle.getOffsetForKeyGroup(keyGroup));
763:             }
764:             serializeStreamStateHandle(keyGroupsStateHandle.getDelegateStateHandle(), dos);
765:         } else {
766:             throw new IOException(
767:                     "Unknown implementation of StreamStateHandle: " + stateHandle.getClass());
768:         }
769:     }
