857:     private static <T extends StateObject> void serializeSingleton(
858:             StateObjectCollection<T> stateObjectCollection,
859:             DataOutputStream dos,
860:             BiConsumerWithException<T, DataOutputStream, IOException> cons)
861:             throws IOException {
862:         final T state = extractSingleton(stateObjectCollection);
863:         if (state != null) {
864:             dos.writeInt(1);
865:             cons.accept(state, dos);
866:         } else {
867:             dos.writeInt(0);
868:         }
