68:     public ForStFlinkFileSystem(
69:             FileSystem delegateFS,
70:             String remoteBase,
71:             String localBase,
72:             @Nullable FileBasedCache fileBasedCache) {
73:         this.localFS = FileSystem.getLocalFileSystem();
74:         this.delegateFS = delegateFS;
