144:     @Override
145:     public synchronized ByteBufferWritableFSDataOutputStream create(
146:             Path dbFilePath, WriteMode overwriteMode) throws IOException {
147:         FileMappingManager.RealPath realPath = fileMappingManager.createFile(dbFilePath);
148:         if (realPath.isLocal) {
149:             return new ByteBufferWritableFSDataOutputStream(
150:                     localFS.create(realPath.path, overwriteMode));
151:         }
152: 
153:         FSDataOutputStream originalOutputStream = delegateFS.create(dbFilePath, overwriteMode);
154:         CachedDataOutputStream cachedDataOutputStream =
155:                 fileBasedCache == null ? null : fileBasedCache.create(originalOutputStream,
156:                         dbFilePath);
157:         return new ByteBufferWritableFSDataOutputStream(
158:                 cachedDataOutputStream == null ? originalOutputStream : cachedDataOutputStream);
159:     }
