163:             throws IOException {
164:         FileMappingManager.RealPath realPath = fileMappingManager.realPath(dbFilePath);
165:         Preconditions.checkNotNull(realPath);
166:         if (realPath.isLocal) {
167:             return new ByteBufferReadableFSDataInputStream(
168:                     () -> localFS.open(realPath.path, bufferSize),
169:                     DEFAULT_INPUT_STREAM_CAPACITY,
170:                     localFS.getFileStatus(realPath.path).getLen());
171:         }
172:         FileStatus fileStatus = checkNotNull(getFileStatus(realPath.path));
173:         return new ByteBufferReadableFSDataInputStream(
174:                 () -> {
175:                     FSDataInputStream inputStream = delegateFS.open(realPath.path, bufferSize);
176:                     CachedDataInputStream cachedDataInputStream =
177:                             fileBasedCache == null
178:                                     ? null
179:                                     : fileBasedCache.open(realPath.path, inputStream);
180:                     return cachedDataInputStream == null ? inputStream : cachedDataInputStream;
181:                 },
182:                 DEFAULT_INPUT_STREAM_CAPACITY,
183:                 fileStatus.getLen());
184:     }
