230:     @Override
231:     public synchronized boolean exists(final Path f) throws IOException {
232:         FileMappingManager.RealPath realPath = fileMappingManager.realPath(f);
233:         if (realPath == null) {
234:             return delegateFS.exists(f) && delegateFS.getFileStatus(f).isDir();
235:         }
236: 
237:         boolean status = false;
238:         if (realPath.isLocal) {
239:             status |= localFS.exists(realPath.path);
240:             if (!status) {
241:                 status = delegateFS.exists(f);
242:             }
243:         } else {
244:             status = delegateFS.exists(realPath.path);
245:         }
246:         return status;
247:     }
248: 
249:     @Override
250:     public synchronized FileStatus getFileStatus(Path path) throws IOException {
251:         FileMappingManager.RealPath realPath = fileMappingManager.realPath(path);
252:         Preconditions.checkNotNull(realPath);
253:         if (realPath.isLocal) {
254:             return localFS.getFileStatus(realPath.path);
255:         }
256:         return delegateFS.getFileStatus(realPath.path);
257:     }
258: 
259:     @Override
260:     public synchronized BlockLocation[] getFileBlockLocations(FileStatus file, long start, long len)
261:             throws IOException {
262:         Path path = file.getPath();
263:         FileMappingManager.RealPath realPath = fileMappingManager.realPath(path);
264:         Preconditions.checkNotNull(realPath);
265:         if (realPath.isLocal) {
266:             FileStatus localFile = localFS.getFileStatus(realPath.path);
267:             return localFS.getFileBlockLocations(localFile, start, len);
268:         }
269:         return delegateFS.getFileBlockLocations(file, start, len);
270:     }
271: 
272:     @Override
273:     public synchronized FileStatus[] listStatus(Path path) throws IOException {
274:         // mapping files
275:         List<FileStatus> fileStatuses = new ArrayList<>();
276:         String pathStr = path.toString();
277:         if (!pathStr.endsWith("/")) {
278:             pathStr += "/";
279:         }
280:         List<String> mappingFiles = fileMappingManager.listByPrefix(pathStr);
281:         for (String mappingFile : mappingFiles) {
282:             String relativePath = mappingFile.substring(pathStr.length());
283:             int slashIndex = relativePath.indexOf('/');
284:             if (slashIndex == -1) { // direct child
285:                 fileStatuses.add(getFileStatus(new Path(mappingFile)));
286:             }
287:         }
288:         return fileStatuses.toArray(new FileStatus[0]);
289:     }
290: 
291:     @Override
292:     public synchronized boolean delete(Path path, boolean recursive) throws IOException {
293:         boolean success = fileMappingManager.deleteFile(path, recursive);
294:         if (fileBasedCache != null) {
295:             // only new generated file will put into cache, no need to consider file mapping
296:             fileBasedCache.delete(path);
297:         }
298:         return success;
299:     }
300: 
301:     @Override
302:     public synchronized boolean mkdirs(Path path) throws IOException {
303:         return delegateFS.mkdirs(path);
304:     }
305: 
306:     @Override
307:     public synchronized boolean isDistributedFS() {
308:         return delegateFS.isDistributedFS();
309:     }
310: 
311:     public synchronized int link(Path src, Path dst) throws IOException {
312:         return fileMappingManager.link(src.toString(), dst.toString());
313:     }
