59: /**
60:  * A {@link PipelineExecutorServiceLoader} that is hardwired to return {@link PipelineExecutor
61:  * PipelineExecutors} that use a given {@link MiniCluster}.
62:  */
63: public class MiniClusterPipelineExecutorServiceLoader implements PipelineExecutorServiceLoader {
64: 
65:     private static final Logger LOG =
66:             LoggerFactory.getLogger(MiniClusterPipelineExecutorServiceLoader.class);
67: 
68:     public static final String NAME = "minicluster";
69: 
70:     private final MiniCluster miniCluster;
71: 
72:     public MiniClusterPipelineExecutorServiceLoader(MiniCluster miniCluster) {
73:         this.miniCluster = miniCluster;
74:     }
75: 
76:     /**
77:      * Populates a {@link Configuration} that is compatible with this {@link
78:      * MiniClusterPipelineExecutorServiceLoader}.
79:      */
80:     public static Configuration updateConfigurationForMiniCluster(
81:             Configuration config, Collection<Path> jarFiles, Collection<URL> classPaths) {
82: 
83:         checkOverridesOption(config, PipelineOptions.JARS);
84:         checkOverridesOption(config, PipelineOptions.CLASSPATHS);
85:         checkOverridesOption(config, DeploymentOptions.TARGET);
86:         checkOverridesOption(config, DeploymentOptions.ATTACHED);
87: 
88:         ConfigUtils.encodeCollectionToConfig(
89:                 config,
90:                 PipelineOptions.JARS,
91:                 jarFiles,
92:                 MiniClusterPipelineExecutorServiceLoader::getAbsoluteURL);
93:         ConfigUtils.encodeCollectionToConfig(
94:                 config, PipelineOptions.CLASSPATHS, classPaths, URL::toString);
95:         config.set(DeploymentOptions.TARGET, MiniClusterPipelineExecutorServiceLoader.NAME);
96:         config.set(DeploymentOptions.ATTACHED, true);
97:         return config;
98:     }
99: 
100:     private static void checkOverridesOption(Configuration config, ConfigOption<?> option) {
101:         if (config.contains(option)) {
102:             LOG.warn("Overriding config setting '{}' for MiniCluster.", option.key());
103:         }
104:     }
105: 
106:     private static String getAbsoluteURL(Path path) {
107:         FileSystem fs;
108:         try {
109:             fs = path.getFileSystem();
110:         } catch (IOException e) {
111:             throw new RuntimeException(String.format("Could not get FileSystem from %s", path), e);
112:         }
113:         try {
114:             return path.makeQualified(fs).toUri().toURL().toString();
115:         } catch (MalformedURLException e) {
116:             throw new RuntimeException(String.format("Could not get URL from %s", path), e);
117:         }
118:     }
119: 
120:     @Override
121:     public PipelineExecutorFactory getExecutorFactory(Configuration configuration) {
122:         return new MiniClusterPipelineExecutorFactory(miniCluster);
123:     }
124: 
125:     @Override
126:     public Stream<String> getExecutorNames() {
127:         return Stream.of(MiniClusterPipelineExecutorServiceLoader.NAME);
128:     }
129: 
130:     private static class MiniClusterPipelineExecutorFactory implements PipelineExecutorFactory {
131:         private final MiniCluster miniCluster;
132: 
133:         public MiniClusterPipelineExecutorFactory(MiniCluster miniCluster) {
134:             this.miniCluster = miniCluster;
135:         }
136: 
137:         @Override
138:         public String getName() {
139:             return MiniClusterPipelineExecutorServiceLoader.NAME;
140:         }
141: 
142:         @Override
143:         public boolean isCompatibleWith(Configuration configuration) {
144:             return true;
145:         }
146: 
147:         @Override
148:         public PipelineExecutor getExecutor(Configuration configuration) {
149:             return new MiniClusterExecutor(miniCluster);
150:         }
151:     }
152: 
153:     private static class MiniClusterExecutor implements CacheSupportedPipelineExecutor {
154:         private final ExecutorService executorService =
155:                 Executors.newFixedThreadPool(
156:                         1, new ExecutorThreadFactory("Flink-MiniClusterExecutor-IO"));
157:         private final MiniCluster miniCluster;
158:         private final List<JobStatusChangedListener> jobStatusChangedListeners;
159: 
160:         public MiniClusterExecutor(MiniCluster miniCluster) {
161:             this.miniCluster = miniCluster;
162:             this.jobStatusChangedListeners =
163:                     JobStatusChangedListenerUtils.createJobStatusChangedListeners(
164:                             Thread.currentThread().getContextClassLoader(),
165:                             miniCluster.getConfiguration(),
166:                             executorService);
167:         }
168: 
169:         @Override
170:         public CompletableFuture<JobClient> execute(
171:                 Pipeline pipeline, Configuration configuration, ClassLoader userCodeClassLoader)
172:                 throws Exception {
173:             final JobGraph executionPlan =
174:                     PipelineExecutorUtils.getExecutionPlan(pipeline, configuration, userCodeClassLoader);
175:             if (executionPlan.getSavepointRestoreSettings() == SavepointRestoreSettings.none()
176:                     && pipeline instanceof StreamGraph) {
177:                 executionPlan.setSavepointRestoreSettings(
178:                         ((StreamGraph) pipeline).getSavepointRestoreSettings());
179:             }
180:             return miniCluster
181:                     .submitJob(executionPlan)
182:                     .whenComplete(
183:                             (ignored, throwable) -> {
184:                                 if (throwable == null) {
185:                                     PipelineExecutorUtils.notifyJobStatusListeners(
186:                                             pipeline, executionPlan, jobStatusChangedListeners);
187:                                 } else {
188:                                     LOG.error(
189:                                             "Failed to submit job graph to mini cluster.",
190:                                             throwable);
191:                                 }
192:                             })
193:                     .thenApply(
194:                             result ->
195:                                     new MiniClusterJobClient(
196:                                             result.getJobID(),
197:                                             miniCluster,
198:                                             userCodeClassLoader,
199:                                             MiniClusterJobClient.JobFinalizationBehavior.NOTHING));
200:         }
201: 
202:         @Override
203:         public CompletableFuture<Set<AbstractID>> listCompletedClusterDatasetIds(
204:                 Configuration configuration, ClassLoader userCodeClassloader) throws Exception {
205:             return miniCluster.listCompletedClusterDatasetIds();
206:         }
207: 
208:         @Override
209:         public CompletableFuture<Void> invalidateClusterDataset(
210:                 AbstractID clusterDatasetId,
211:                 Configuration configuration,
212:                 ClassLoader userCodeClassloader)
213:                 throws Exception {
214:             return miniCluster.invalidateClusterDataset(clusterDatasetId);
215:         }
216:     }
217: }
