677:     private static List<String> extractRelativizedURLsForJarsFromDirectory(File directory)
678:             throws MalformedURLException {
679:         Preconditions.checkArgument(
680:                 directory.listFiles() != null,
681:                 "The passed File does not seem to be a directory or is not accessible: "
682:                         + directory.getAbsolutePath());
683: 
684:         final List<String> relativizedURLs = new ArrayList<>();
685:         final Path workingDirectory = FileUtils.getCurrentWorkingDirectory();
686:         for (File file : Preconditions.checkNotNull(directory.listFiles())) {
687:             if (!FileUtils.isJarFile(file.toPath())) {
688:                 // any non-JARs are filtered by PackagedProgramRetrieverImpl
689:                 continue;
690:             }
691: 
692:             Path relativePath = FileUtils.relativizePath(workingDirectory, file.toPath());
693:             relativizedURLs.add(FileUtils.toURL(relativePath).toString());
694:         }
695: 
696:         return relativizedURLs;
697:     }
