96:      *
97:      * @param pipeline the pipeline that contains lineage graph information.
98:      * @param executionPlan executionPlan that contains job basic info
99:      * @param listeners the list of job status changed listeners
100:      */
101:     public static void notifyJobStatusListeners(
102:             @Nonnull final Pipeline pipeline,
103:             @Nonnull final JobGraph executionPlan,
104:             List<JobStatusChangedListener> listeners) {
105:         RuntimeExecutionMode executionMode =
106:                 executionPlan.getJobConfiguration().get(ExecutionOptions.RUNTIME_MODE);
107:         listeners.forEach(
108:                 listener -> {
109:                     try {
110:                         listener.onEvent(
111:                                 new DefaultJobCreatedEvent(
112:                                         executionPlan.getJobID(),
113:                                         executionPlan.getName(),
114:                                         ((StreamGraph) pipeline).getLineageGraph(),
115:                                         executionMode));
116:                     } catch (Throwable e) {
117:                         LOG.error(
118:                                 "Fail to notify job status changed listener {}",
119:                                 listener.getClass().getName(),
120:                                 e);
121:                     }
122:                 });
123:     }
