324:     private static void callMainMethod(Class<?> entryClass, String[] args)
325:             throws ProgramInvocationException {
326:         Method mainMethod;
327:         if (!Modifier.isPublic(entryClass.getModifiers())) {
328:             throw new ProgramInvocationException(
329:                     "The class " + entryClass.getName() + " must be public.");
330:         }
331: 
332:         try {
333:             mainMethod = entryClass.getMethod("main", String[].class);
334:         } catch (NoSuchMethodException e) {
335:             throw new ProgramInvocationException(
336:                     "The class " + entryClass.getName() + " has no main(String[]) method.");
337:         } catch (Throwable t) {
338:             throw new ProgramInvocationException(
339:                     "Could not look up the main(String[]) method from the class "
340:                             + entryClass.getName()
341:                             + ": "
342:                             + t.getMessage(),
343:                     t);
344:         }
345: 
346:         if (!Modifier.isStatic(mainMethod.getModifiers())) {
347:             throw new ProgramInvocationException(
348:                     "The class " + entryClass.getName() + " declares a non-static main method.");
349:         }
350:         if (!Modifier.isPublic(mainMethod.getModifiers())) {
351:             throw new ProgramInvocationException(
352:                     "The class " + entryClass.getName() + " declares a non-public main method.");
353:         }
354: 
355:         try {
356:             mainMethod.invoke(null, (Object) args);
357:         } catch (IllegalArgumentException e) {
358:             throw new ProgramInvocationException(
359:                     "Could not invoke the main method, arguments are not matching.", e);
360:         } catch (IllegalAccessException e) {
361:             throw new ProgramInvocationException(
362:                     "Access to the main method was denied: " + e.getMessage(), e);
363:         } catch (InvocationTargetException e) {
364:             Throwable exceptionInMethod = e.getTargetException();
365:             if (exceptionInMethod instanceof Error) {
366:                 throw (Error) exceptionInMethod;
367:             } else if (exceptionInMethod instanceof ProgramParametrizationException) {
368:                 throw (ProgramParametrizationException) exceptionInMethod;
369:             } else if (exceptionInMethod instanceof ProgramInvocationException) {
370:                 throw (ProgramInvocationException) exceptionInMethod;
371:             } else {
372:                 throw new ProgramInvocationException(
373:                         "The main method caused an error: " + exceptionInMethod.getMessage(),
374:                         exceptionInMethod);
375:             }
376:         } catch (Throwable t) {
377:             throw new ProgramInvocationException(
378:                     "An error occurred while invoking the program's main method: " + t.getMessage(),
379:                     t);
380:         }
381:     }
