614:     private static void checkJarFile(URL jarfile) throws ProgramInvocationException {
615:         try {
616:             JarUtils.checkJarFile(jarfile);
617:         } catch (IOException e) {
618:             throw new ProgramInvocationException(e.getMessage(), e);
619:         } catch (Throwable t) {
620:             throw new ProgramInvocationException(
621:                     "Cannot access jar file"
622:                             + (t.getMessage() == null ? "." : ": " + t.getMessage()),
623:                     t);
624:         }
625:     }
