305:     private static boolean hasMainMethod(Class<?> entryClass) {
306:         Method mainMethod;
307:         try {
308:             mainMethod = entryClass.getMethod("main", String[].class);
309:         } catch (NoSuchMethodException e) {
310:             return false;
311:         } catch (Throwable t) {
312:             throw new RuntimeException(
313:                     "Could not look up the main(String[]) method from the class "
314:                             + entryClass.getName()
315:                             + ": "
316:                             + t.getMessage(),
317:                     t);
318:         }
319: 
320:         return Modifier.isStatic(mainMethod.getModifiers())
321:                 && Modifier.isPublic(mainMethod.getModifiers());
322:     }
