677:             this.configuration = configuration;
678:             return this;
679:         }
680: 
681:         public Builder setSavepointRestoreSettings(
682:                 SavepointRestoreSettings savepointRestoreSettings) {
683:             this.savepointRestoreSettings = savepointRestoreSettings;
684:             return this;
685:         }
686: 
687:         @VisibleForTesting
688:         public List<URL> getUserClassPaths() {
689:             return userClassPaths;
690:         }
691: 
692:         public PackagedProgram build() throws ProgramInvocationException {
693:             if (jarFile == null && entryPointClassName == null) {
694:                 throw new IllegalArgumentException(
695:                         "The jarFile and entryPointClassName can not be null at the same time.");
696:             }
697:             return new PackagedProgram(
698:                     jarFile,
699:                     userClassPaths,
700:                     entryPointClassName,
701:                     configuration,
702:                     savepointRestoreSettings,
703:                     args);
704:         }
705: 
706:         private Builder() {}
707:     }
