1032:     private static void testMaterializedResult(
1033:             DataStream<Row> dataStream, int primaryKeyPos, Row... expectedResult) throws Exception {
1034:         try (CloseableIterator<Row> iterator = dataStream.executeAndCollect()) {
1035:             final List<Row> materializedResult = new ArrayList<>();
1036:             iterator.forEachRemaining(
1037:                     row -> {
1038:                         final RowKind kind = row.getKind();
1039:                         row.setKind(RowKind.INSERT);
1040:                         switch (kind) {
1041:                             case UPDATE_AFTER:
1042:                                 final Object primaryKeyValue = row.getField(primaryKeyPos);
1043:                                 assertThat(primaryKeyValue).isNotNull();
1044:                                 materializedResult.removeIf(
1045:                                         r -> primaryKeyValue.equals(r.getField(primaryKeyPos)));
1046:                                 // fall through
1047:                             case INSERT:
1048:                                 materializedResult.add(row);
1049:                                 break;
1050:                             case UPDATE_BEFORE:
1051:                             case DELETE:
1052:                                 materializedResult.remove(row);
1053:                                 break;
1054:                         }
1055:                     });
1056:             assertThat(materializedResult).containsExactlyInAnyOrder(expectedResult);
1057:         }
1058:     }
