920:                                 + "FROM (VALUES ('Bob'), ('Alice'), ('Greg'), ('Bob')) AS NameTable(name) "
921:                                 + "WHERE name IN (SELECT allowedName FROM AllowedNamesTable)"
922:                                 + "GROUP BY name");
923: 
924:         final DataStream<Row> nameCountStream = tableEnv.toChangelogStream(nameCountTable);
925: 
926:         final DataStream<Tuple2<String, Long>> updatesPerNameStream =
927:                 nameCountStream
928:                         .keyBy(r -> r.<String>getFieldAs("name"))
929:                         .process(
930:                                 new KeyedProcessFunction<String, Row, Tuple2<String, Long>>() {
931: 
932:                                     ValueState<Long> count;
933: 
934:                                     @Override
935:                                     public void open(OpenContext openContext) {
936:                                         count =
937:                                                 getRuntimeContext()
938:                                                         .getState(
939:                                                                 new ValueStateDescriptor<>(
940:                                                                         "count", Long.class));
941:                                     }
942: 
943:                                     @Override
944:                                     public void processElement(
945:                                             Row r, Context ctx, Collector<Tuple2<String, Long>> out)
946:                                             throws IOException {
947:                                         Long currentCount = count.value();
948:                                         if (currentCount == null) {
949:                                             currentCount = 0L;
950:                                         }
951:                                         final long updatedCount = currentCount + 1;
952:                                         count.update(updatedCount);
953: 
954:                                         out.collect(Tuple2.of(ctx.getCurrentKey(), updatedCount));
955:                                     }
956:                                 });
957: 
958:         tableEnv.createTemporaryView("UpdatesPerName", updatesPerNameStream);
959: 
960:         return tableEnv.sqlQuery("SELECT DISTINCT f0, f1 FROM UpdatesPerName");
