1050:     private static void testMaterializedResult(
1051:             DataStream<Row> dataStream, int primaryKeyPos, Row... expectedResult) throws Exception {
1052:         try (CloseableIterator<Row> iterator = dataStream.executeAndCollect()) {
1053:             final List<Row> materializedResult = new ArrayList<>();
1054:             iterator.forEachRemaining(
1055:                     row -> {
1056:                         final RowKind kind = row.getKind();
1057:                         row.setKind(RowKind.INSERT);
1058:                         switch (kind) {
1059:                             case UPDATE_AFTER:
1060:                                 final Object primaryKeyValue = row.getField(primaryKeyPos);
1061:                                 assertThat(primaryKeyValue).isNotNull();
1062:                                 materializedResult.removeIf(
1063:                                         r -> primaryKeyValue.equals(r.getField(primaryKeyPos)));
1064:                                 // fall through
1065:                             case INSERT:
1066:                                 materializedResult.add(row);
1067:                                 break;
1068:                             case UPDATE_BEFORE:
1069:                             case DELETE:
1070:                                 materializedResult.remove(row);
1071:                                 break;
1072:                         }
1073:                     });
1074:             assertThat(materializedResult).containsExactlyInAnyOrder(expectedResult);
1075:         }
1076:     }
