278:             final PipelineExecutorServiceLoader executorServiceLoader,
279:             final Configuration configuration,
280:             final ClassLoader userClassloader) {
281:         this.executorServiceLoader = checkNotNull(executorServiceLoader);
282:         this.configuration = new Configuration(checkNotNull(configuration));
283:         this.config = new ExecutionConfig(this.configuration);
284:         this.checkpointCfg = new CheckpointConfig(this.configuration);
285:         this.userClassloader =
286:                 userClassloader == null ? getClass().getClassLoader() : userClassloader;
287: 
288:         // the configuration of a job or an operator can be specified at the following places:
289:         //     i) at the operator level via e.g. parallelism by using the
290:         // SingleOutputStreamOperator.setParallelism().
291:         //     ii) programmatically by using e.g. the env.setRestartStrategy() method
292:         //     iii) in the configuration passed here
293:         //
294:         // if specified in multiple places, the priority order is the above.
295:         //
296:         // Given this, it is safe to overwrite the execution config default values here because all
297:         // other ways assume
298:         // that the env is already instantiated so they will overwrite the value passed here.
299:         this.configure(this.configuration, this.userClassloader);
300:     }
