1088:     /**
1089:      * Creates a new data stream that contains the given elements. The elements must all be of the
1090:      * same type, for example, all of the {@link String} or {@link Integer}.
1091:      *
1092:      * <p>The framework will try and determine the exact type from the elements. In case of generic
1093:      * elements, it may be necessary to manually supply the type information via {@link
1094:      * #fromData(org.apache.flink.api.common.typeinfo.TypeInformation, OUT...)}.
1095:      *
1096:      * <p>NOTE: This creates a non-parallel data stream source by default (parallelism of one).
1097:      * Adjustment of parallelism is supported via {@code setParallelism()} on the result.
1098:      *
1099:      * @param data The array of elements to create the data stream from.
1100:      * @param <OUT> The type of the returned data stream
1101:      * @return The data stream representing the given array of elements
1102:      */
1103:     @SafeVarargs
1104:     public final <OUT> DataStreamSource<OUT> fromData(OUT... data) {
1105:         if (data.length == 0) {
1106:             throw new IllegalArgumentException(
1107:                     "fromElements needs at least one element as argument");
1108:         }
1109: 
1110:         TypeInformation<OUT> typeInfo;
1111:         try {
1112:             typeInfo = TypeExtractor.getForObject(data[0]);
1113:         } catch (Exception e) {
1114:             throw new RuntimeException(
1115:                     "Could not create TypeInformation for type "
1116:                             + data[0].getClass().getName()
1117:                             + "; please specify the TypeInformation manually via "
1118:                             + "StreamExecutionEnvironment#fromData(Collection, TypeInformation)",
1119:                     e);
1120:         }
1121:         return fromData(Arrays.asList(data), typeInfo);
1122:     }
