2010:     private <OUT> DataStreamSource<OUT> createFileInput(
2011:             FileInputFormat<OUT> inputFormat,
2012:             TypeInformation<OUT> typeInfo,
2013:             String sourceName,
2014:             FileProcessingMode monitoringMode,
2015:             long interval) {
2016: 
2017:         Preconditions.checkNotNull(inputFormat, "Unspecified file input format.");
2018:         Preconditions.checkNotNull(typeInfo, "Unspecified output type information.");
2019:         Preconditions.checkNotNull(sourceName, "Unspecified name for the source.");
2020:         Preconditions.checkNotNull(monitoringMode, "Unspecified monitoring mode.");
2021: 
2022:         Preconditions.checkArgument(
2023:                 monitoringMode.equals(FileProcessingMode.PROCESS_ONCE)
2024:                         || interval >= ContinuousFileMonitoringFunction.MIN_MONITORING_INTERVAL,
2025:                 "The path monitoring interval cannot be less than "
2026:                         + ContinuousFileMonitoringFunction.MIN_MONITORING_INTERVAL
2027:                         + " ms.");
2028: 
2029:         ContinuousFileMonitoringFunction<OUT> monitoringFunction =
2030:                 new ContinuousFileMonitoringFunction<>(
2031:                         inputFormat, monitoringMode, getParallelism(), interval);
2032: 
2033:         ContinuousFileReaderOperatorFactory<OUT, TimestampedFileInputSplit> factory =
2034:                 new ContinuousFileReaderOperatorFactory<>(inputFormat);
