2044:                         // ContinuousFileMonitoringFunction to 1 in
2045:                         // case reactive mode changes it. See FLINK-28274 for more information.
2046:                         .forceNonParallel()
2047:                         .transform("Split Reader: " + sourceName, typeInfo, factory);
