2266:     /**
2267:      * Triggers the program execution. The environment will execute all parts of the program that
2268:      * have resulted in a "sink" operation. Sink operations are for example printing results or
2269:      * forwarding them to a message queue.
2270:      *
2271:      * @param streamGraph the stream graph representing the transformations
2272:      * @return The result of the job execution, containing elapsed time and accumulators.
2273:      * @throws Exception which occurs during job execution.
2274:      */
2275:     @Internal
2276:     public JobExecutionResult execute(StreamGraph streamGraph) throws Exception {
2277:         final JobClient jobClient = executeAsync(streamGraph);
2278: 
2279:         try {
2280:             final JobExecutionResult jobExecutionResult;
2281: 
2282:             if (configuration.get(DeploymentOptions.ATTACHED)) {
2283:                 jobExecutionResult = jobClient.getJobExecutionResult().get();
2284:             } else {
2285:                 jobExecutionResult = new DetachedJobExecutionResult(jobClient.getJobID());
2286:             }
2287: 
2288:             jobListeners.forEach(
2289:                     jobListener -> jobListener.onJobExecuted(jobExecutionResult, null));
2290: 
2291:             return jobExecutionResult;
2292:         } catch (Throwable t) {
2293:             // get() on the JobExecutionResult Future will throw an ExecutionException. This
2294:             // behaviour was largely not there in Flink versions before the PipelineExecutor
2295:             // refactoring so we should strip that exception.
2296:             Throwable strippedException = ExceptionUtils.stripExecutionException(t);
2297: 
2298:             jobListeners.forEach(
2299:                     jobListener -> {
2300:                         jobListener.onJobExecuted(null, strippedException);
2301:                     });
2302:             ExceptionUtils.rethrowException(strippedException);
2303: 
2304:             // never reached, only make javac happy
2305:             return null;
2306:         }
2307:     }
