1038:     /**
1039:      * Sets all relevant options contained in the {@link ReadableConfig}. It will reconfigure {@link
1040:      * StreamExecutionEnvironment}, {@link ExecutionConfig} and {@link CheckpointConfig}.
1041:      *
1042:      * <p>It will change the value of a setting only if a corresponding option was set in the {@code
1043:      * configuration}. If a key is not present, the current value of a field will remain untouched.
1044:      *
1045:      * @param configuration a configuration to read the values from
1046:      * @param classLoader a class loader to use when loading classes
1047:      */
1048:     @PublicEvolving
1049:     public void configure(ReadableConfig configuration, ClassLoader classLoader) {
1050:         this.configuration.addAll(Configuration.fromMap(configuration.toMap()));
1051:         configuration
1052:                 .getOptional(DeploymentOptions.JOB_LISTENERS)
1053:                 .ifPresent(listeners -> registerCustomListeners(classLoader, listeners));
1054:         configuration
1055:                 .getOptional(PipelineOptions.CACHED_FILES)
1056:                 .ifPresent(
1057:                         f -> {
1058:                             this.cacheFile.clear();
1059:                             this.cacheFile.addAll(DistributedCache.parseCachedFilesFromString(f));
1060:                         });
1061: 
1062:         config.configure(configuration, classLoader);
1063:         checkpointCfg.configure(configuration);
1064: 
1065:         // reset state backend for backward compatibility
1066:         configuration
1067:                 .getOptional(StateBackendOptions.STATE_BACKEND)
1068:                 .ifPresent(ignored -> this.defaultStateBackend = null);
1069:     }
