1071:     private void registerCustomListeners(
1072:             final ClassLoader classLoader, final List<String> listeners) {
1073:         for (String listener : listeners) {
1074:             try {
1075:                 final JobListener jobListener =
1076:                         InstantiationUtil.instantiate(listener, JobListener.class, classLoader);
1077:                 jobListeners.add(jobListener);
1078:             } catch (FlinkException e) {
1079:                 throw new WrappingRuntimeException("Could not load JobListener : " + listener, e);
1080:             }
1081:         }
1082:     }
