1232:     private static <OUT> TypeInformation<OUT> extractTypeInfoFromCollection(Collection<OUT> data) {
1233:         Preconditions.checkNotNull(data, "Collection must not be null");
1234:         if (data.isEmpty()) {
1235:             throw new IllegalArgumentException("Collection must not be empty");
1236:         }
1237: 
1238:         OUT first = data.iterator().next();
1239:         if (first == null) {
1240:             throw new IllegalArgumentException("Collection must not contain null elements");
1241:         }
1242: 
1243:         TypeInformation<OUT> typeInfo;
1244:         try {
1245:             typeInfo = TypeExtractor.getForObject(first);
1246:         } catch (Exception e) {
1247:             throw new RuntimeException(
1248:                     "Could not create TypeInformation for type "
1249:                             + first.getClass()
1250:                             + "; please specify the TypeInformation manually via the version of the "
1251:                             + "method that explicitly accepts it as an argument.",
1252:                     e);
1253:         }
1254:         return typeInfo;
1255:     }
