2363:      * program that have resulted in a "sink" operation. Sink operations are for example printing
2364:      * results or forwarding them to a message queue.
2365:      *
2366:      * <p>The program execution will be logged and displayed with the provided name
2367:      *
2368:      * @param jobName desired name of the job
2369:      * @return A {@link JobClient} that can be used to communicate with the submitted job, completed
2370:      *     on submission succeeded.
2371:      * @throws Exception which occurs during job execution.
2372:      */
2373:     @PublicEvolving
2374:     public JobClient executeAsync(String jobName) throws Exception {
2375:         final StreamGraph streamGraph = getStreamGraph();
2376:         if (jobName != null) {
2377:             streamGraph.setJobName(jobName);
2378:         }
2379:         return executeAsync(streamGraph);
2380:     }
2381: 
2382:     /**
2383:      * Triggers the program execution asynchronously. The environment will execute all parts of the
2384:      * program that have resulted in a "sink" operation. Sink operations are for example printing
2385:      * results or forwarding them to a message queue.
2386:      *
2387:      * @param streamGraph the stream graph representing the transformations
2388:      * @return A {@link JobClient} that can be used to communicate with the submitted job, completed
2389:      *     on submission succeeded.
2390:      * @throws Exception which occurs during job execution.
2391:      */
2392:     @Internal
2393:     public JobClient executeAsync(StreamGraph streamGraph) throws Exception {
2394:         checkNotNull(streamGraph, "StreamGraph cannot be null.");
2395:         final PipelineExecutor executor = getPipelineExecutor();
2396: 
2397:         CompletableFuture<JobClient> jobClientFuture =
2398:                 executor.execute(streamGraph, configuration, userClassloader);
2399: 
2400:         try {
2401:             JobClient jobClient = jobClientFuture.get();
2402:             jobListeners.forEach(jobListener -> jobListener.onJobSubmitted(jobClient, null));
2403:             collectIterators.forEach(iterator -> iterator.setJobClient(jobClient));
2404:             collectIterators.clear();
2405:             return jobClient;
2406:         } catch (ExecutionException executionException) {
2407:             final Throwable strippedException =
2408:                     ExceptionUtils.stripExecutionException(executionException);
2409:             jobListeners.forEach(
2410:                     jobListener -> jobListener.onJobSubmitted(null, strippedException));
2411: 
2412:             throw new FlinkException(
2413:                     String.format("Failed to execute job '%s'.", streamGraph.getJobName()),
2414:                     strippedException);
2415:         }
2416:     }
