2452:     private void synchronizeClusterDatasetStatus() {
2453:         if (cachedTransformations.isEmpty()) {
2454:             return;
2455:         }
2456:         Set<AbstractID> completedClusterDatasets =
2457:                 listCompletedClusterDatasets().stream()
2458:                         .map(AbstractID::new)
2459:                         .collect(Collectors.toSet());
2460:         cachedTransformations.forEach(
2461:                 (id, transformation) -> {
2462:                     transformation.setCached(completedClusterDatasets.contains(id));
2463:                 });
