2480:     private StreamGraphGenerator getStreamGraphGenerator(List<Transformation<?>> transformations) {
2481:         if (transformations.size() <= 0) {
2482:             throw new IllegalStateException(
2483:                     "No operators defined in streaming topology. Cannot execute.");
2484:         }
2485: 
2486:         // Synchronize the cached file to config option PipelineOptions.CACHED_FILES because the
2487:         // field cachedFile haven't been migrated to configuration.
2488:         if (!getCachedFiles().isEmpty()) {
2489:             configuration.set(
2490:                     PipelineOptions.CACHED_FILES,
2491:                     DistributedCache.parseStringFromCachedFiles(getCachedFiles()));
2492:         }
2493: 
2494:         // We copy the transformation so that newly added transformations cannot intervene with the
2495:         // stream graph generation.
2496:         return new StreamGraphGenerator(
2497:                         new ArrayList<>(transformations), config, checkpointCfg, configuration)
2498:                 .setStateBackend(defaultStateBackend)
2499:                 .setTimeCharacteristic(getStreamTimeCharacteristic())
2500:                 .setSlotSharingGroupResource(slotSharingGroupResources);
2501:     }
