2840:     private <OUT, T extends TypeInformation<OUT>> T getTypeInfo(
2841:             Object source,
2842:             String sourceName,
2843:             Class<?> baseSourceClass,
2844:             TypeInformation<OUT> typeInfo) {
2845:         TypeInformation<OUT> resolvedTypeInfo = typeInfo;
2846:         if (resolvedTypeInfo == null && source instanceof ResultTypeQueryable) {
2847:             resolvedTypeInfo = ((ResultTypeQueryable<OUT>) source).getProducedType();
2848:         }
2849:         if (resolvedTypeInfo == null) {
2850:             try {
2851:                 resolvedTypeInfo =
2852:                         TypeExtractor.createTypeInfo(
2853:                                 baseSourceClass, source.getClass(), 0, null, null);
2854:             } catch (final InvalidTypesException e) {
2855:                 resolvedTypeInfo = (TypeInformation<OUT>) new MissingTypeInfo(sourceName, e);
2856:             }
2857:         }
2858:         return (T) resolvedTypeInfo;
