41: /** Several integration tests for queryable state using the {@link FsStateBackend}. */
42: public class NonHAQueryableStateFsBackendITCase extends AbstractQueryableStateTestBase {
43: 
44:     // NUM_TMS * NUM_SLOTS_PER_TM must match the parallelism of the pipelines so that
45:     // we always use all TaskManagers so that the JM oracle is always properly re-registered
46:     private static final int NUM_TMS = 2;
47:     private static final int NUM_SLOTS_PER_TM = 2;
48:     private static final int NUM_PORT_COUNT = 100;
49: 
50:     private static final int QS_PROXY_PORT_RANGE_START = 9084;
51:     private static final int QS_SERVER_PORT_RANGE_START = 9089;
52: 
53:     @TempDir static Path tmpStateBackendDir;
54: 
55:     @RegisterExtension
56:     static final MiniClusterExtension MINI_CLUSTER_RESOURCE =
57:             new MiniClusterExtension(
58:                     () ->
59:                             new MiniClusterResourceConfiguration.Builder()
60:                                     .setConfiguration(getConfig())
61:                                     .setNumberTaskManagers(NUM_TMS)
62:                                     .setNumberSlotsPerTaskManager(NUM_SLOTS_PER_TM)
63:                                     .build());
64: 
65:     @Override
66:     protected StateBackend createStreamExecutionEnvironment() throws Exception {
67:         return new FsStateBackend(tmpStateBackendDir.toUri().toString());
68:     }
69: 
70:     @BeforeAll
71:     static void setup(@InjectClusterClient RestClusterClient<?> injectedClusterClient)
72:             throws Exception {
73:         client = new QueryableStateClient("localhost", QS_PROXY_PORT_RANGE_START);
74: 
75:         clusterClient = injectedClusterClient;
76:     }
77: 
78:     @AfterAll
79:     static void tearDown() {
80:         client.shutdownAndWait();
81:     }
82: 
83:     private static Configuration getConfig() {
84:         Configuration config = new Configuration();
85:         config.set(QueryableStateOptions.ENABLE_QUERYABLE_STATE_PROXY_SERVER, true);
86:         config.set(TaskManagerOptions.MANAGED_MEMORY_SIZE, MemorySize.parse("4m"));
87:         config.set(TaskManagerOptions.MINI_CLUSTER_NUM_TASK_MANAGERS, NUM_TMS);
88:         config.set(TaskManagerOptions.NUM_TASK_SLOTS, NUM_SLOTS_PER_TM);
89:         config.set(QueryableStateOptions.CLIENT_NETWORK_THREADS, 1);
90:         config.set(QueryableStateOptions.PROXY_NETWORK_THREADS, 1);
91:         config.set(QueryableStateOptions.SERVER_NETWORK_THREADS, 1);
92:         config.set(
93:                 QueryableStateOptions.PROXY_PORT_RANGE,
94:                 QS_PROXY_PORT_RANGE_START + "-" + (QS_PROXY_PORT_RANGE_START + NUM_PORT_COUNT));
95:         config.set(
96:                 QueryableStateOptions.SERVER_PORT_RANGE,
97:                 QS_SERVER_PORT_RANGE_START + "-" + (QS_SERVER_PORT_RANGE_START + NUM_PORT_COUNT));
98:         config.set(WebOptions.SUBMIT_ENABLE, false);
99:         return config;
100:     }
