426:     public CompletableFuture<Void> registerProducedPartitions(TaskManagerLocation location) {
427: 
428:         assertRunningInJobMasterMainThread();
429: 
430:         return FutureUtils.thenApplyAsyncIfNotDone(
431:                 registerProducedPartitions(vertex, location, attemptId),
432:                 vertex.getExecutionGraphAccessor().getJobMasterMainThreadExecutor(),
433:                 producedPartitionsCache -> {
434:                     producedPartitions = producedPartitionsCache;
435: 
436:                     if (getState() == SCHEDULED) {
437:                         startTrackingPartitions(
438:                                 location.getResourceID(), producedPartitionsCache.values());
439:                     } else {
440:                         LOG.info(
441:                                 "Discarding late registered partitions for {} task {}.",
442:                                 getState(),
443:                                 attemptId);
444:                         for (ResultPartitionDeploymentDescriptor desc :
445:                                 producedPartitionsCache.values()) {
446:                             getVertex()
447:                                     .getExecutionGraphAccessor()
448:                                     .getShuffleMaster()
449:                                     .releasePartitionExternally(desc.getShuffleDescriptor());
450:                         }
451:                     }
452:                     return null;
453:                 });
454:     }
