678:     public void cancel() {
679:         // depending on the previous state, we go directly to cancelled (no cancel call necessary)
680:         // -- or to canceling (cancel call needs to be sent to the task manager)
681: 
682:         // because of several possibly previous states, we need to again loop until we make a
683:         // successful atomic state transition
684:         assertRunningInJobMasterMainThread();
685:         while (true) {
686: 
687:             ExecutionState current = this.state;
688: 
689:             if (current == CANCELING || current == CANCELED) {
690:                 // already taken care of, no need to cancel again
691:                 return;
692:             }
693: 
694:             // these two are the common cases where we need to send a cancel call
695:             else if (current == INITIALIZING || current == RUNNING || current == DEPLOYING) {
696:                 // try to transition to canceling, if successful, send the cancel call
697:                 if (startCancelling(NUM_CANCEL_CALL_TRIES)) {
698:                     return;
699:                 }
700:                 // else: fall through the loop
701:             } else if (current == FINISHED) {
702:                 // finished before it could be cancelled.
703:                 // in any case, the task is removed from the TaskManager already
704: 
705:                 // a pipelined partition whose consumer has never been deployed could still be
706:                 // buffered on the TM
707:                 // release it here since pipelined partitions for FINISHED executions aren't handled
708:                 // elsewhere
709:                 // covers the following cases:
710:                 // 		a) restarts of this vertex
711:                 // 		b) a global failure (which may result in a FAILED job state)
712:                 sendReleaseIntermediateResultPartitionsRpcCall();
713: 
714:                 return;
715:             } else if (current == FAILED) {
716:                 // failed before it could be cancelled.
717:                 // in any case, the task is removed from the TaskManager already
718: 
719:                 return;
720:             } else if (current == CREATED || current == SCHEDULED) {
721:                 // from here, we can directly switch to cancelled, because no task has been deployed
722:                 if (cancelAtomically()) {
723:                     return;
724:                 }
725:                 // else: fall through the loop
726:             } else {
727:                 throw new IllegalStateException(current.name());
728:             }
729:         }
730:     }
731: 
732:     public CompletableFuture<?> suspend() {
733:         switch (state) {
734:             case RUNNING:
735:             case INITIALIZING:
736:             case DEPLOYING:
737:             case CREATED:
738:             case SCHEDULED:
739:                 if (!cancelAtomically()) {
740:                     throw new IllegalStateException(
741:                             String.format(
742:                                     "Could not directly go to %s from %s.",
743:                                     CANCELED.name(), state.name()));
744:                 }
745:                 break;
746:             case CANCELING:
747:                 completeCancelling();
748:                 break;
749:             case FINISHED:
750:                 // a pipelined partition whose consumer has never been deployed could still be
751:                 // buffered on the TM
752:                 // release it here since pipelined partitions for FINISHED executions aren't handled
753:                 // elsewhere
754:                 // most notably, the TaskExecutor does not release pipelined partitions when
755:                 // disconnecting from the JM
756:                 sendReleaseIntermediateResultPartitionsRpcCall();
757:                 break;
758:             case FAILED:
759:             case CANCELED:
760:                 break;
761:             default:
762:                 throw new IllegalStateException(state.name());
763:         }
764: 
765:         return releaseFuture;
766:     }
