1060: 
1061:     void completeCancelling(
1062:             Map<String, Accumulator<?, ?>> userAccumulators,
1063:             IOMetrics metrics,
1064:             boolean releasePartitions) {
1065: 
1066:         // the taskmanagers can themselves cancel tasks without an external trigger, if they find
1067:         // that the
1068:         // network stack is canceled (for example by a failing / canceling receiver or sender
1069:         // this is an artifact of the old network runtime, but for now we need to support task
1070:         // transitions
1071:         // from running directly to canceled
1072: 
1073:         while (true) {
1074:             ExecutionState current = this.state;
1075: 
1076:             if (current == CANCELED) {
1077:                 return;
1078:             } else if (current == CANCELING
1079:                     || current == RUNNING
1080:                     || current == INITIALIZING
1081:                     || current == DEPLOYING) {
1082: 
1083:                 updateAccumulatorsAndMetrics(userAccumulators, metrics);
1084: 
1085:                 if (transitionState(current, CANCELED)) {
1086:                     finishCancellation(releasePartitions);
1087:                     return;
1088:                 }
1089: 
1090:                 // else fall through the loop
1091:             } else {
1092:                 // failing in the meantime may happen and is no problem.
1093:                 // anything else is a serious problem !!!
1094:                 if (current != FAILED) {
1095:                     String message =
1096:                             String.format(
1097:                                     "Asynchronous race: Found %s in state %s after successful cancel call.",
1098:                                     vertex.getTaskNameWithSubtaskIndex(), state);
1099:                     LOG.error(message);
1100:                     vertex.getExecutionGraphAccessor().failGlobal(new Exception(message));
1101:                 }
1102:                 return;
1103:             }
1104:         }
1105:     }
