1589:     /**
1590:      * Wrapper class implementing {@link CheckpointStatsListener} in a way that checkpoint-related
1591:      * events are actually executed in the {@code AdaptiveScheduler}'s main thread.
1592:      */
1593:     private CheckpointStatsListener createCheckpointStatsListener() {
1594: 
1595:         return new CheckpointStatsListener() {
1596: 
1597:             @Override
1598:             public void onFailedCheckpoint() {
1599:                 runIfSupported(CheckpointStatsListener::onFailedCheckpoint, "onFailedCheckpoint");
1600:             }
1601: 
1602:             @Override
1603:             public void onCompletedCheckpoint() {
1604:                 runIfSupported(
1605:                         CheckpointStatsListener::onCompletedCheckpoint, "onCompletedCheckpoint");
1606:             }
1607: 
1608:             private void runIfSupported(
1609:                     ThrowingConsumer<CheckpointStatsListener, RuntimeException> callback,
1610:                     String callbackLabel) {
1611:                 AdaptiveScheduler.this
1612:                         .getMainThreadExecutor()
1613:                         .execute(
1614:                                 () ->
1615:                                         state.tryRun(
1616:                                                 CheckpointStatsListener.class,
1617:                                                 callback,
1618:                                                 logger ->
