275:     private static List<ColumnDescriptor> getAllColumnDescriptorByType(
276:             int depth, Type type, List<ColumnDescriptor> columns) throws ParquetRuntimeException {
277:         List<ColumnDescriptor> res = new ArrayList<>();
278:         for (ColumnDescriptor descriptor : columns) {
279:             if (depth >= descriptor.getPath().length) {
280:                 throw new InvalidSchemaException("Corrupted Parquet schema");
281:             }
282:             if (type.getName().equals(descriptor.getPath()[depth])) {
283:                 res.add(descriptor);
284:             }
285:         }
286: 
287:         // If doesn't find the type descriptor in corresponding depth, throw exception
288:         if (res.isEmpty()) {
289:             throw new InvalidSchemaException(
290:                     "Failed to find related Parquet column descriptor with type " + type);
291:         }
292:         return res;
293:     }
