295:     public static ColumnReader createColumnReader(
296:             boolean isUtcTimestamp,
297:             LogicalType fieldType,
298:             Type type,
299:             List<ColumnDescriptor> columnDescriptors,
300:             PageReadStore pages,
301:             int depth)
302:             throws IOException {
303:         List<ColumnDescriptor> descriptors =
304:                 getAllColumnDescriptorByType(depth, type, columnDescriptors);
305:         switch (fieldType.getTypeRoot()) {
306:             case BOOLEAN:
307:                 return new BooleanColumnReader(
308:                         descriptors.get(0), pages.getPageReader(descriptors.get(0)));
309:             case TINYINT:
310:                 return new ByteColumnReader(
311:                         descriptors.get(0), pages.getPageReader(descriptors.get(0)));
312:             case DOUBLE:
313:                 return new DoubleColumnReader(
314:                         descriptors.get(0), pages.getPageReader(descriptors.get(0)));
315:             case FLOAT:
316:                 return new FloatColumnReader(
317:                         descriptors.get(0), pages.getPageReader(descriptors.get(0)));
318:             case INTEGER:
319:             case DATE:
320:             case TIME_WITHOUT_TIME_ZONE:
321:                 return new IntColumnReader(
322:                         descriptors.get(0), pages.getPageReader(descriptors.get(0)));
323:             case BIGINT:
324:                 return new LongColumnReader(
325:                         descriptors.get(0), pages.getPageReader(descriptors.get(0)));
326:             case SMALLINT:
327:                 return new ShortColumnReader(
328:                         descriptors.get(0), pages.getPageReader(descriptors.get(0)));
329:             case CHAR:
330:             case VARCHAR:
331:             case BINARY:
332:             case VARBINARY:
333:                 return new BytesColumnReader(
334:                         descriptors.get(0), pages.getPageReader(descriptors.get(0)));
335:             case TIMESTAMP_WITHOUT_TIME_ZONE:
336:             case TIMESTAMP_WITH_LOCAL_TIME_ZONE:
337:                 return new TimestampColumnReader(
338:                         isUtcTimestamp,
339:                         descriptors.get(0),
340:                         pages.getPageReader(descriptors.get(0)));
341:             case DECIMAL:
342:                 switch (descriptors.get(0).getPrimitiveType().getPrimitiveTypeName()) {
343:                     case INT32:
344:                         return new IntColumnReader(
345:                                 descriptors.get(0), pages.getPageReader(descriptors.get(0)));
346:                     case INT64:
347:                         return new LongColumnReader(
348:                                 descriptors.get(0), pages.getPageReader(descriptors.get(0)));
349:                     case BINARY:
350:                         return new BytesColumnReader(
351:                                 descriptors.get(0), pages.getPageReader(descriptors.get(0)));
352:                     case FIXED_LEN_BYTE_ARRAY:
353:                         return new FixedLenBytesColumnReader(
354:                                 descriptors.get(0),
355:                                 pages.getPageReader(descriptors.get(0)),
356:                                 ((DecimalType) fieldType).getPrecision());
357:                 }
358:             case ARRAY:
359:                 return new ArrayColumnReader(
360:                         descriptors.get(0),
361:                         pages.getPageReader(descriptors.get(0)),
362:                         isUtcTimestamp,
363:                         descriptors.get(0).getPrimitiveType(),
364:                         fieldType);
365:             case MAP:
366:                 MapType mapType = (MapType) fieldType;
367:                 ArrayColumnReader mapKeyReader =
368:                         new ArrayColumnReader(
369:                                 descriptors.get(0),
370:                                 pages.getPageReader(descriptors.get(0)),
371:                                 isUtcTimestamp,
372:                                 descriptors.get(0).getPrimitiveType(),
373:                                 new ArrayType(mapType.getKeyType()));
374:                 ArrayColumnReader mapValueReader =
375:                         new ArrayColumnReader(
376:                                 descriptors.get(1),
377:                                 pages.getPageReader(descriptors.get(1)),
378:                                 isUtcTimestamp,
379:                                 descriptors.get(1).getPrimitiveType(),
380:                                 new ArrayType(mapType.getValueType()));
381:                 return new MapColumnReader(mapKeyReader, mapValueReader);
382:             case MULTISET:
383:                 MultisetType multisetType = (MultisetType) fieldType;
384:                 ArrayColumnReader multisetKeyReader =
385:                         new ArrayColumnReader(
386:                                 descriptors.get(0),
387:                                 pages.getPageReader(descriptors.get(0)),
388:                                 isUtcTimestamp,
389:                                 descriptors.get(0).getPrimitiveType(),
390:                                 new ArrayType(multisetType.getElementType()));
391:                 ArrayColumnReader multisetValueReader =
392:                         new ArrayColumnReader(
393:                                 descriptors.get(1),
394:                                 pages.getPageReader(descriptors.get(1)),
395:                                 isUtcTimestamp,
396:                                 descriptors.get(1).getPrimitiveType(),
397:                                 new ArrayType(new IntType(false)));
398:                 return new MapColumnReader(multisetKeyReader, multisetValueReader);
399:             case ROW:
400:                 RowType rowType = (RowType) fieldType;
401:                 GroupType groupType = type.asGroupType();
402:                 List<ColumnReader> fieldReaders = new ArrayList<>();
403:                 for (int i = 0; i < rowType.getFieldCount(); i++) {
404:                     fieldReaders.add(
405:                             createColumnReader(
406:                                     isUtcTimestamp,
407:                                     rowType.getTypeAt(i),
408:                                     groupType.getType(i),
409:                                     descriptors,
410:                                     pages,
411:                                     depth + 1));
412:                 }
413:                 return new RowColumnReader(fieldReaders);
414:             default:
415:                 throw new UnsupportedOperationException(fieldType + " is not supported now.");
416:         }
417:     }
