419:     public static WritableColumnVector createWritableColumnVector(
420:             int batchSize,
421:             LogicalType fieldType,
422:             Type type,
423:             List<ColumnDescriptor> columnDescriptors,
424:             int depth) {
425:         List<ColumnDescriptor> descriptors =
426:                 getAllColumnDescriptorByType(depth, type, columnDescriptors);
427:         PrimitiveType primitiveType = descriptors.get(0).getPrimitiveType();
428:         PrimitiveType.PrimitiveTypeName typeName = primitiveType.getPrimitiveTypeName();
429:         switch (fieldType.getTypeRoot()) {
430:             case BOOLEAN:
431:                 checkArgument(
432:                         typeName == PrimitiveType.PrimitiveTypeName.BOOLEAN,
433:                         "Unexpected type: %s",
434:                         typeName);
435:                 return new HeapBooleanVector(batchSize);
436:             case TINYINT:
437:                 checkArgument(
438:                         typeName == PrimitiveType.PrimitiveTypeName.INT32,
439:                         "Unexpected type: %s",
440:                         typeName);
441:                 return new HeapByteVector(batchSize);
442:             case DOUBLE:
443:                 checkArgument(
444:                         typeName == PrimitiveType.PrimitiveTypeName.DOUBLE,
445:                         "Unexpected type: %s",
446:                         typeName);
447:                 return new HeapDoubleVector(batchSize);
448:             case FLOAT:
449:                 checkArgument(
450:                         typeName == PrimitiveType.PrimitiveTypeName.FLOAT,
451:                         "Unexpected type: %s",
452:                         typeName);
453:                 return new HeapFloatVector(batchSize);
454:             case INTEGER:
455:             case DATE:
456:             case TIME_WITHOUT_TIME_ZONE:
457:                 checkArgument(
458:                         typeName == PrimitiveType.PrimitiveTypeName.INT32,
459:                         "Unexpected type: %s",
460:                         typeName);
461:                 return new HeapIntVector(batchSize);
462:             case BIGINT:
463:                 checkArgument(
464:                         typeName == PrimitiveType.PrimitiveTypeName.INT64,
465:                         "Unexpected type: %s",
466:                         typeName);
467:                 return new HeapLongVector(batchSize);
468:             case SMALLINT:
469:                 checkArgument(
470:                         typeName == PrimitiveType.PrimitiveTypeName.INT32,
471:                         "Unexpected type: %s",
472:                         typeName);
473:                 return new HeapShortVector(batchSize);
474:             case CHAR:
475:             case VARCHAR:
476:             case BINARY:
477:             case VARBINARY:
478:                 checkArgument(
479:                         typeName == PrimitiveType.PrimitiveTypeName.BINARY,
480:                         "Unexpected type: %s",
481:                         typeName);
482:                 return new HeapBytesVector(batchSize);
483:             case TIMESTAMP_WITHOUT_TIME_ZONE:
484:             case TIMESTAMP_WITH_LOCAL_TIME_ZONE:
485:                 checkArgument(
486:                         typeName == PrimitiveType.PrimitiveTypeName.INT96
487:                                 || typeName == PrimitiveType.PrimitiveTypeName.INT64,
488:                         "Unexpected type: %s",
489:                         typeName);
490:                 return new HeapTimestampVector(batchSize);
491:             case DECIMAL:
492:                 DecimalType decimalType = (DecimalType) fieldType;
493:                 if (ParquetSchemaConverter.is32BitDecimal(decimalType.getPrecision())) {
494:                     checkArgument(
495:                             (typeName == PrimitiveType.PrimitiveTypeName.FIXED_LEN_BYTE_ARRAY
496:                                             || typeName == PrimitiveType.PrimitiveTypeName.INT32)
497:                                     && primitiveType.getOriginalType() == OriginalType.DECIMAL,
498:                             "Unexpected type: %s",
499:                             typeName);
500:                     return new HeapIntVector(batchSize);
501:                 } else if (ParquetSchemaConverter.is64BitDecimal(decimalType.getPrecision())) {
502:                     checkArgument(
503:                             (typeName == PrimitiveType.PrimitiveTypeName.FIXED_LEN_BYTE_ARRAY
504:                                             || typeName == PrimitiveType.PrimitiveTypeName.INT64)
505:                                     && primitiveType.getOriginalType() == OriginalType.DECIMAL,
506:                             "Unexpected type: %s",
507:                             typeName);
508:                     return new HeapLongVector(batchSize);
509:                 } else {
510:                     checkArgument(
511:                             (typeName == PrimitiveType.PrimitiveTypeName.FIXED_LEN_BYTE_ARRAY
512:                                             || typeName == PrimitiveType.PrimitiveTypeName.BINARY)
513:                                     && primitiveType.getOriginalType() == OriginalType.DECIMAL,
514:                             "Unexpected type: %s",
515:                             typeName);
516:                     return new HeapBytesVector(batchSize);
517:                 }
518:             case ARRAY:
519:                 ArrayType arrayType = (ArrayType) fieldType;
520:                 return new HeapArrayVector(
521:                         batchSize,
522:                         createWritableColumnVector(
523:                                 batchSize,
524:                                 arrayType.getElementType(),
525:                                 type,
526:                                 columnDescriptors,
527:                                 depth));
528:             case MAP:
529:                 MapType mapType = (MapType) fieldType;
530:                 GroupType mapRepeatedType = type.asGroupType().getType(0).asGroupType();
531:                 return new HeapMapVector(
532:                         batchSize,
533:                         createWritableColumnVector(
534:                                 batchSize,
535:                                 mapType.getKeyType(),
536:                                 mapRepeatedType.getType(0),
537:                                 descriptors,
538:                                 depth + 2),
539:                         createWritableColumnVector(
540:                                 batchSize,
541:                                 mapType.getValueType(),
542:                                 mapRepeatedType.getType(1),
543:                                 descriptors,
544:                                 depth + 2));
545:             case MULTISET:
546:                 MultisetType multisetType = (MultisetType) fieldType;
547:                 GroupType multisetRepeatedType = type.asGroupType().getType(0).asGroupType();
548:                 return new HeapMapVector(
549:                         batchSize,
550:                         createWritableColumnVector(
551:                                 batchSize,
552:                                 multisetType.getElementType(),
553:                                 multisetRepeatedType.getType(0),
554:                                 descriptors,
555:                                 depth + 2),
556:                         createWritableColumnVector(
557:                                 batchSize,
558:                                 new IntType(false),
559:                                 multisetRepeatedType.getType(1),
560:                                 descriptors,
561:                                 depth + 2));
562:             case ROW:
563:                 RowType rowType = (RowType) fieldType;
564:                 GroupType groupType = type.asGroupType();
565:                 WritableColumnVector[] columnVectors =
566:                         new WritableColumnVector[rowType.getFieldCount()];
567:                 for (int i = 0; i < columnVectors.length; i++) {
568:                     columnVectors[i] =
569:                             createWritableColumnVector(
570:                                     batchSize,
571:                                     rowType.getTypeAt(i),
572:                                     groupType.getType(i),
573:                                     descriptors,
574:                                     depth + 1);
575:                 }
576:                 return new HeapRowVector(batchSize, columnVectors);
577:             default:
578:                 throw new UnsupportedOperationException(fieldType + " is not supported now.");
579:         }
