432:     private DataStreamSink<?> createBatchCompactSink(
433:             DataStream<RowData> dataStream,
434:             DataStructureConverter converter,
435:             HiveWriterFactory recordWriterFactory,
436:             TableMetaStoreFactory metaStoreFactory,
437:             OutputFileConfig fileNaming,
438:             String stagingParentDir,
439:             StorageDescriptor sd,
440:             Properties tableProps,
441:             boolean isToLocal,
442:             boolean overwrite,
443:             final int sinkParallelism,
444:             final int compactParallelism,
445:             boolean sinkParallelismConfigured,
446:             boolean compactParallelismConfigured)
447:             throws IOException {
448:         String[] partitionColumns = getPartitionKeyArray();
449:         org.apache.flink.configuration.Configuration conf =
450:                 new org.apache.flink.configuration.Configuration();
451:         catalogTable.getOptions().forEach(conf::setString);
452:         HadoopFileSystemFactory fsFactory = fsFactory();
453:         org.apache.flink.core.fs.Path tmpPath =
454:                 new org.apache.flink.core.fs.Path(toStagingDir(stagingParentDir, jobConf));
455: 
456:         PartitionCommitPolicyFactory partitionCommitPolicyFactory =
457:                 new PartitionCommitPolicyFactory(
458:                         conf.get(HiveOptions.SINK_PARTITION_COMMIT_POLICY_KIND),
459:                         conf.get(FileSystemConnectorOptions.SINK_PARTITION_COMMIT_POLICY_CLASS),
460:                         conf.get(
461:                                 FileSystemConnectorOptions.SINK_PARTITION_COMMIT_SUCCESS_FILE_NAME),
462:                         conf.get(
463:                                 FileSystemConnectorOptions
464:                                         .SINK_PARTITION_COMMIT_POLICY_CLASS_PARAMETERS));
465: 
466:         org.apache.flink.core.fs.Path path = new org.apache.flink.core.fs.Path(sd.getLocation());
467:         BucketsBuilder<RowData, String, ? extends BucketsBuilder<RowData, ?, ?>> builder =
468:                 getBucketsBuilder(path, recordWriterFactory, sd, fileNaming, conf);
469: 
470:         CompactReader.Factory<RowData> readerFactory = createCompactReaderFactory(sd, tableProps);
471: 
472:         HiveOutputFormatFactory outputFormatFactory =
473:                 new HiveOutputFormatFactory(recordWriterFactory);
474:         HiveRowPartitionComputer partitionComputer =
475:                 new HiveRowPartitionComputer(
476:                         hiveShim,
477:                         JobConfUtils.getDefaultPartitionName(jobConf),
478:                         resolvedSchema.getColumnNames().toArray(new String[0]),
479:                         resolvedSchema.getColumnDataTypes().toArray(new DataType[0]),
480:                         partitionColumns);
481: 
482:         SingleOutputStreamOperator<Row> map =
483:                 dataStream.map(value -> (Row) converter.toExternal(value));
484:         map.getTransformation().setParallelism(sinkParallelism, sinkParallelismConfigured);
485: 
486:         DataStream<CoordinatorInput> writerDataStream =
487:                 map.transform(
488:                         BATCH_COMPACT_WRITER_OP_NAME,
489:                         TypeInformation.of(CoordinatorInput.class),
490:                         new BatchFileWriter<>(
491:                                 fsFactory,
492:                                 tmpPath,
493:                                 partitionColumns,
494:                                 dynamicGrouping,
495:                                 staticPartitionSpec,
496:                                 outputFormatFactory,
497:                                 partitionComputer,
498:                                 fileNaming));
499:         writerDataStream
500:                 .getTransformation()
501:                 .setParallelism(sinkParallelism, sinkParallelismConfigured);
502: 
503:         long compactAverageSize = conf.get(HiveOptions.COMPACT_SMALL_FILES_AVG_SIZE).getBytes();
504: 
505:         long compactTargetSize =
506:                 conf.getOptional(FileSystemConnectorOptions.COMPACTION_FILE_SIZE)
507:                         .orElse(conf.get(SINK_ROLLING_POLICY_FILE_SIZE))
508:                         .getBytes();
509: 
510:         return BatchSink.createBatchCompactSink(
511:                 writerDataStream,
512:                 builder,
513:                 readerFactory,
514:                 fsFactory,
515:                 metaStoreFactory,
516:                 partitionCommitPolicyFactory,
517:                 partitionColumns,
518:                 staticPartitionSpec,
519:                 tmpPath,
520:                 identifier,
521:                 compactAverageSize,
522:                 compactTargetSize,
523:                 isToLocal,
524:                 overwrite,
525:                 compactParallelism,
526:                 compactParallelismConfigured);
527:     }
