529:     private BucketsBuilder<RowData, String, ? extends BucketsBuilder<RowData, ?, ?>>
530:             getBucketsBuilder(
531:                     org.apache.flink.core.fs.Path path,
532:                     HiveWriterFactory recordWriterFactory,
533:                     StorageDescriptor sd,
534:                     OutputFileConfig fileNaming,
535:                     org.apache.flink.configuration.Configuration conf) {
536:         HiveRowDataPartitionComputer partComputer =
537:                 new HiveRowDataPartitionComputer(
538:                         hiveShim,
539:                         JobConfUtils.getDefaultPartitionName(jobConf),
540:                         resolvedSchema.getColumnNames().toArray(new String[0]),
541:                         resolvedSchema.getColumnDataTypes().toArray(new DataType[0]),
542:                         getPartitionKeyArray());
543:         TableBucketAssigner assigner = new TableBucketAssigner(partComputer);
544:         HiveRollingPolicy rollingPolicy =
545:                 new HiveRollingPolicy(
546:                         conf.get(SINK_ROLLING_POLICY_FILE_SIZE).getBytes(),
547:                         conf.get(SINK_ROLLING_POLICY_ROLLOVER_INTERVAL).toMillis(),
548:                         conf.get(SINK_ROLLING_POLICY_INACTIVITY_INTERVAL).toMillis());
549: 
550:         BucketsBuilder<RowData, String, ? extends BucketsBuilder<RowData, ?, ?>> builder;
551:         if (fallbackMappedWriter) {
552:             builder =
553:                     bucketsBuilderForMRWriter(
554:                             recordWriterFactory, sd, assigner, rollingPolicy, fileNaming);
555:             LOG.info("Hive sink: Use MapReduce RecordWriter writer.");
556:         } else {
557:             Optional<BulkWriter.Factory<RowData>> bulkFactory =
558:                     createBulkWriterFactory(getPartitionKeyArray(), sd);
559:             if (bulkFactory.isPresent()) {
560:                 builder =
561:                         StreamingFileSink.forBulkFormat(
562:                                         path,
563:                                         new FileSystemTableSink.ProjectionBulkFactory(
564:                                                 bulkFactory.get(), partComputer))
565:                                 .withBucketAssigner(assigner)
566:                                 .withRollingPolicy(rollingPolicy)
567:                                 .withOutputFileConfig(fileNaming);
568:                 LOG.info("Hive sink: Use native parquet&orc writer.");
569:             } else {
570:                 builder =
571:                         bucketsBuilderForMRWriter(
572:                                 recordWriterFactory, sd, assigner, rollingPolicy, fileNaming);
573:                 LOG.info(
574:                         "Hive sink: Use MapReduce RecordWriter writer because BulkWriter Factory not available.");
575:             }
576:         }
577:         return builder;
578:     }
