580:     private DataStreamSink<Row> createBatchNoCompactSink(
581:             DataStream<RowData> dataStream,
582:             DataStructureConverter converter,
583:             HiveWriterFactory recordWriterFactory,
584:             TableMetaStoreFactory metaStoreFactory,
585:             OutputFileConfig fileNaming,
586:             String stagingParentDir,
587:             boolean isToLocal,
588:             final int sinkParallelism,
589:             boolean sinkParallelismConfigured)
590:             throws IOException {
591:         org.apache.flink.configuration.Configuration conf =
592:                 new org.apache.flink.configuration.Configuration();
593:         catalogTable.getOptions().forEach(conf::setString);
594:         FileSystemOutputFormat.Builder<Row> builder = new FileSystemOutputFormat.Builder<>();
595:         builder.setPartitionComputer(
596:                 new HiveRowPartitionComputer(
597:                         hiveShim,
598:                         JobConfUtils.getDefaultPartitionName(jobConf),
599:                         resolvedSchema.getColumnNames().toArray(new String[0]),
600:                         resolvedSchema.getColumnDataTypes().toArray(new DataType[0]),
601:                         getPartitionKeyArray()));
602:         builder.setDynamicGrouped(dynamicGrouping);
603:         builder.setPartitionColumns(getPartitionKeyArray());
604:         builder.setFileSystemFactory(fsFactory());
605:         builder.setFormatFactory(new HiveOutputFormatFactory(recordWriterFactory));
606:         builder.setMetaStoreFactory(metaStoreFactory);
607:         builder.setOverwrite(overwrite);
608:         builder.setIsToLocal(isToLocal);
609:         builder.setStaticPartitions(staticPartitionSpec);
610:         builder.setStagingPath(
611:                 new org.apache.flink.core.fs.Path(toStagingDir(stagingParentDir, jobConf)));
612:         builder.setOutputFileConfig(fileNaming);
613:         builder.setIdentifier(identifier);
614:         builder.setPartitionCommitPolicyFactory(
615:                 new PartitionCommitPolicyFactory(
616:                         conf.get(HiveOptions.SINK_PARTITION_COMMIT_POLICY_KIND),
617:                         conf.get(FileSystemConnectorOptions.SINK_PARTITION_COMMIT_POLICY_CLASS),
618:                         conf.get(
619:                                 FileSystemConnectorOptions.SINK_PARTITION_COMMIT_SUCCESS_FILE_NAME),
620:                         conf.get(
621:                                 FileSystemConnectorOptions
622:                                         .SINK_PARTITION_COMMIT_POLICY_CLASS_PARAMETERS)));
623:         return BatchSink.createBatchNoCompactSink(
624:                 dataStream, converter, builder.build(), sinkParallelism, sinkParallelismConfigured);
625:     }
