202:     @Override
203:     protected List<OUT> executeOnCollections(
204:             List<IN1> input1, List<IN2> input2, RuntimeContext ctx, ExecutionConfig config)
205:             throws Exception {
206:         // --------------------------------------------------------------------
207:         // Setup
208:         // --------------------------------------------------------------------
209:         TypeInformation<IN1> inputType1 = getOperatorInfo().getFirstInputType();
210:         TypeInformation<IN2> inputType2 = getOperatorInfo().getSecondInputType();
211: 
212:         // for the grouping / merging comparator
213:         int[] inputKeys1 = getKeyColumns(0);
214:         int[] inputKeys2 = getKeyColumns(1);
215: 
216:         boolean[] inputDirections1 = new boolean[inputKeys1.length];
217:         boolean[] inputDirections2 = new boolean[inputKeys2.length];
218:         Arrays.fill(inputDirections1, true);
219:         Arrays.fill(inputDirections2, true);
220: 
221:         final TypeSerializer<IN1> inputSerializer1 = inputType1.createSerializer(config);
222:         final TypeSerializer<IN2> inputSerializer2 = inputType2.createSerializer(config);
223: 
224:         final TypeComparator<IN1> inputComparator1 =
225:                 getTypeComparator(config, inputType1, inputKeys1, inputDirections1);
226:         final TypeComparator<IN2> inputComparator2 =
227:                 getTypeComparator(config, inputType2, inputKeys2, inputDirections2);
228: 
229:         final TypeComparator<IN1> inputSortComparator1;
230:         final TypeComparator<IN2> inputSortComparator2;
231: 
232:         if (groupOrder1 == null || groupOrder1.getNumberOfFields() == 0) {
233:             // no group sorting
234:             inputSortComparator1 = inputComparator1;
235:         } else {
236:             // group sorting
237:             int[] groupSortKeys = groupOrder1.getFieldPositions();
238:             int[] allSortKeys = new int[inputKeys1.length + groupOrder1.getNumberOfFields()];
239:             System.arraycopy(inputKeys1, 0, allSortKeys, 0, inputKeys1.length);
240:             System.arraycopy(
241:                     groupSortKeys, 0, allSortKeys, inputKeys1.length, groupSortKeys.length);
242: 
243:             boolean[] groupSortDirections = groupOrder1.getFieldSortDirections();
244:             boolean[] allSortDirections = new boolean[inputKeys1.length + groupSortKeys.length];
245:             Arrays.fill(allSortDirections, 0, inputKeys1.length, true);
246:             System.arraycopy(
247:                     groupSortDirections,
248:                     0,
249:                     allSortDirections,
250:                     inputKeys1.length,
251:                     groupSortDirections.length);
252: 
253:             inputSortComparator1 =
254:                     getTypeComparator(config, inputType1, allSortKeys, allSortDirections);
255:         }
256: 
257:         if (groupOrder2 == null || groupOrder2.getNumberOfFields() == 0) {
258:             // no group sorting
259:             inputSortComparator2 = inputComparator2;
260:         } else {
261:             // group sorting
262:             int[] groupSortKeys = groupOrder2.getFieldPositions();
263:             int[] allSortKeys = new int[inputKeys2.length + groupOrder2.getNumberOfFields()];
264:             System.arraycopy(inputKeys2, 0, allSortKeys, 0, inputKeys2.length);
265:             System.arraycopy(
266:                     groupSortKeys, 0, allSortKeys, inputKeys2.length, groupSortKeys.length);
267: 
268:             boolean[] groupSortDirections = groupOrder2.getFieldSortDirections();
269:             boolean[] allSortDirections = new boolean[inputKeys2.length + groupSortKeys.length];
270:             Arrays.fill(allSortDirections, 0, inputKeys2.length, true);
271:             System.arraycopy(
272:                     groupSortDirections,
273:                     0,
274:                     allSortDirections,
275:                     inputKeys2.length,
276:                     groupSortDirections.length);
277: 
278:             inputSortComparator2 =
279:                     getTypeComparator(config, inputType2, allSortKeys, allSortDirections);
280:         }
281: 
282:         CoGroupSortListIterator<IN1, IN2> coGroupIterator =
283:                 new CoGroupSortListIterator<IN1, IN2>(
284:                         input1,
285:                         inputSortComparator1,
286:                         inputComparator1,
287:                         inputSerializer1,
288:                         input2,
289:                         inputSortComparator2,
290:                         inputComparator2,
291:                         inputSerializer2);
292: 
293:         // --------------------------------------------------------------------
294:         // Run UDF
295:         // --------------------------------------------------------------------
296:         CoGroupFunction<IN1, IN2, OUT> function = userFunction.getUserCodeObject();
297: 
298:         FunctionUtils.setFunctionRuntimeContext(function, ctx);
299:         FunctionUtils.openFunction(function, DefaultOpenContext.INSTANCE);
300: 
301:         List<OUT> result = new ArrayList<OUT>();
302:         Collector<OUT> resultCollector =
303:                 new CopyingListCollector<OUT>(
304:                         result,
305:                         getOperatorInfo().getOutputType().createSerializer(config));
306: 
307:         while (coGroupIterator.next()) {
308:             function.coGroup(
309:                     coGroupIterator.getValues1(), coGroupIterator.getValues2(), resultCollector);
310:         }
311: 
312:         FunctionUtils.closeFunction(function);
313: 
314:         return result;
315:     }
