251:                                 .createComparator(sortColumns, sortOrderings, 0, executionConfig);
252:             } else if (inputType instanceof AtomicType) {
253:                 sortComparator =
254:                         ((AtomicType<IN>) inputType)
255:                                 .createComparator(sortOrderings[0], executionConfig);
256:             } else {
257:                 throw new UnsupportedOperationException(
258:                         "Local output sorting does not support type " + inputType + " yet.");
259:             }
