216:     /**
217:      * Accepts the visitor and applies it this instance. This method applies the visitor in a
218:      * depth-first traversal. The visitors pre-visit method is called and, if returning
219:      * <tt>true</tt>, the visitor is recursively applied on the single input. After the recursion
220:      * returned, the post-visit method is called.
221:      *
222:      * @param visitor The visitor.
223:      * @see org.apache.flink.util.Visitable#accept(org.apache.flink.util.Visitor)
224:      */
225:     @Override
226:     public void accept(Visitor<Operator<?>> visitor) {
227:         boolean descend = visitor.preVisit(this);
228:         if (descend) {
229:             this.input.accept(visitor);
230:             visitor.postVisit(this);
231:         }
232:     }
