52: /**
53:  * The result of {@link DataStream#project(int...)}. This can be used to add more fields to the
54:  * projection.
55:  */
56: @PublicEvolving
57: public class StreamProjection<IN> {
58: 
59:     private DataStream<IN> dataStream;
60:     private int[] fieldIndexes;
61: 
62:     protected StreamProjection(DataStream<IN> dataStream, int[] fieldIndexes) {
63:         if (!dataStream.getType().isTupleType()) {
64:             throw new RuntimeException("Only Tuple DataStreams can be projected");
65:         }
66:         if (fieldIndexes.length == 0) {
67:             throw new IllegalArgumentException("project() needs to select at least one (1) field.");
68:         } else if (fieldIndexes.length > Tuple.MAX_ARITY - 1) {
69:             throw new IllegalArgumentException(
70:                     "project() may select only up to (" + (Tuple.MAX_ARITY - 1) + ") fields.");
71:         }
72: 
73:         int maxFieldIndex = (dataStream.getType()).getArity();
74:         for (int i = 0; i < fieldIndexes.length; i++) {
75:             Preconditions.checkElementIndex(fieldIndexes[i], maxFieldIndex);
76:         }
77: 
78:         this.dataStream = dataStream;
79:         this.fieldIndexes = fieldIndexes;
80:     }
