82:     /**
83:      * Chooses a projectTupleX according to the length of {@link
84:      * org.apache.flink.streaming.api.datastream.StreamProjection#fieldIndexes}.
85:      *
86:      * @return The projected DataStream.
87:      * @see org.apache.flink.api.java.operators.ProjectOperator.Projection
88:      */
89:     @SuppressWarnings("unchecked")
90:     public <OUT extends Tuple> SingleOutputStreamOperator<OUT> projectTupleX() {
91:         SingleOutputStreamOperator<OUT> projOperator = null;
92: 
93:         switch (fieldIndexes.length) {
94:             case 1:
95:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple1();
96:                 break;
97:             case 2:
98:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple2();
99:                 break;
100:             case 3:
101:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple3();
102:                 break;
103:             case 4:
104:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple4();
105:                 break;
106:             case 5:
107:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple5();
108:                 break;
109:             case 6:
110:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple6();
111:                 break;
112:             case 7:
113:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple7();
114:                 break;
115:             case 8:
116:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple8();
117:                 break;
118:             case 9:
119:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple9();
120:                 break;
121:             case 10:
122:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple10();
123:                 break;
124:             case 11:
125:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple11();
126:                 break;
127:             case 12:
128:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple12();
129:                 break;
130:             case 13:
131:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple13();
132:                 break;
133:             case 14:
134:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple14();
135:                 break;
136:             case 15:
137:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple15();
138:                 break;
139:             case 16:
140:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple16();
141:                 break;
142:             case 17:
143:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple17();
144:                 break;
145:             case 18:
146:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple18();
147:                 break;
148:             case 19:
149:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple19();
150:                 break;
151:             case 20:
152:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple20();
153:                 break;
154:             case 21:
155:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple21();
156:                 break;
157:             case 22:
158:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple22();
159:                 break;
160:             case 23:
161:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple23();
162:                 break;
163:             case 24:
164:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple24();
165:                 break;
166:             case 25:
167:                 projOperator = (SingleOutputStreamOperator<OUT>) projectTuple25();
168:                 break;
169:             default:
170:                 throw new IllegalStateException("Excessive arity in tuple.");
171:         }
172: 
173:         return projOperator;
174:     }
