208:         public OuterJoinListIterator(
209:                 List<IN1> leftInput,
210:                 TypeSerializer<IN1> leftSerializer,
211:                 final TypeComparator<IN1> leftComparator,
212:                 List<IN2> rightInput,
213:                 TypeSerializer<IN2> rightSerializer,
214:                 final TypeComparator<IN2> rightComparator,
215:                 OuterJoinType outerJoinType) {
216:             this.outerJoinType = outerJoinType;
217:             pairComparator = new GenericPairComparator<>(leftComparator, rightComparator);
218:             leftGroupedIterator =
219:                     new ListKeyGroupedIterator<>(leftInput, leftSerializer, leftComparator);
220:             rightGroupedIterator =
221:                     new ListKeyGroupedIterator<>(rightInput, rightSerializer, rightComparator);
222:             // ----------------------------------------------------------------
223:             // Sort
224:             // ----------------------------------------------------------------
225:             Collections.sort(
226:                     leftInput,
227:                     new Comparator<IN1>() {
228:                         @Override
229:                         public int compare(IN1 o1, IN1 o2) {
230:                             return leftComparator.compare(o1, o2);
231:                         }
232:                     });
233: 
234:             Collections.sort(
235:                     rightInput,
236:                     new Comparator<IN2>() {
237:                         @Override
238:                         public int compare(IN2 o1, IN2 o2) {
239:                             return rightComparator.compare(o1, o2);
240:                         }
241:                     });
242:         }
