244:         @SuppressWarnings("unchecked")
245:         private boolean next() throws IOException {
246:             boolean hasMoreElements;
247:             if ((currLeftIterator == null || !currLeftIterator.hasNext())
248:                     && (currRightIterator == null || !currRightIterator.hasNext())) {
249:                 hasMoreElements = nextGroups(outerJoinType);
250:                 if (hasMoreElements) {
251:                     if (outerJoinType != OuterJoinType.LEFT) {
252:                         currLeftIterator = new ListIteratorWrapper(currLeftSubset.iterator());
253:                     }
254:                     leftReturn = (IN1) currLeftIterator.next();
255:                     if (outerJoinType != OuterJoinType.RIGHT) {
256:                         currRightIterator = new ListIteratorWrapper(currRightSubset.iterator());
257:                     }
258:                     rightReturn = (IN2) currRightIterator.next();
259:                     return true;
260:                 } else {
261:                     // no more elements
262:                     return false;
263:                 }
264:             } else if (currLeftIterator.hasNext() && !currRightIterator.hasNext()) {
265:                 leftReturn = (IN1) currLeftIterator.next();
266:                 currRightIterator.reset();
267:                 rightReturn = (IN2) currRightIterator.next();
268:                 return true;
269:             } else {
270:                 rightReturn = (IN2) currRightIterator.next();
271:                 return true;
272:             }
273:         }
