275:         private boolean nextGroups(OuterJoinType outerJoinType) throws IOException {
276:             if (outerJoinType == OuterJoinType.FULL) {
277:                 return nextGroups();
278:             } else if (outerJoinType == OuterJoinType.LEFT) {
279:                 boolean leftContainsElements = false;
280:                 while (!leftContainsElements && nextGroups()) {
281:                     currLeftIterator = new ListIteratorWrapper(currLeftSubset.iterator());
282:                     if (currLeftIterator.next() != null) {
283:                         leftContainsElements = true;
284:                     }
285:                     currLeftIterator.reset();
286:                 }
287:                 return leftContainsElements;
288:             } else if (outerJoinType == OuterJoinType.RIGHT) {
289:                 boolean rightContainsElements = false;
290:                 while (!rightContainsElements && nextGroups()) {
291:                     currRightIterator = new ListIteratorWrapper(currRightSubset.iterator());
292:                     if (currRightIterator.next() != null) {
293:                         rightContainsElements = true;
294:                     }
295:                     currRightIterator.reset();
296:                 }
297:                 return rightContainsElements;
298:             } else {
299:                 throw new IllegalArgumentException(
300:                         "Outer join of type '" + outerJoinType + "' not supported.");
301:             }
302:         }
303: 
304:         private boolean nextGroups() throws IOException {
305:             boolean firstEmpty = true;
306:             boolean secondEmpty = true;
307: 
308:             if (this.matchStatus != MatchStatus.FIRST_EMPTY) {
309:                 if (this.matchStatus == MatchStatus.FIRST_REMAINED) {
310:                     // comparator is still set correctly
311:                     firstEmpty = false;
312:                 } else {
313:                     if (this.leftGroupedIterator.nextKey()) {
314:                         this.pairComparator.setReference(
315:                                 leftGroupedIterator.getValues().getCurrent());
316:                         firstEmpty = false;
317:                     }
318:                 }
319:             }
320: 
321:             if (this.matchStatus != MatchStatus.SECOND_EMPTY) {
322:                 if (this.matchStatus == MatchStatus.SECOND_REMAINED) {
323:                     secondEmpty = false;
324:                 } else {
325:                     if (rightGroupedIterator.nextKey()) {
326:                         secondEmpty = false;
327:                     }
328:                 }
329:             }
330: 
331:             if (firstEmpty && secondEmpty) {
332:                 // both inputs are empty
333:                 return false;
334:             } else if (firstEmpty && !secondEmpty) {
335:                 // input1 is empty, input2 not
336:                 this.currLeftSubset = Collections.singleton(null);
337:                 this.currRightSubset = this.rightGroupedIterator.getValues();
338:                 this.matchStatus = MatchStatus.FIRST_EMPTY;
339:                 return true;
340:             } else if (!firstEmpty && secondEmpty) {
341:                 // input1 is not empty, input 2 is empty
342:                 this.currLeftSubset = this.leftGroupedIterator.getValues();
343:                 this.currRightSubset = Collections.singleton(null);
344:                 this.matchStatus = MatchStatus.SECOND_EMPTY;
345:                 return true;
346:             } else {
347:                 // both inputs are not empty
348:                 final int comp =
349:                         this.pairComparator.compareToReference(
350:                                 rightGroupedIterator.getValues().getCurrent());
351: 
352:                 if (0 == comp) {
353:                     // keys match
354:                     this.currLeftSubset = this.leftGroupedIterator.getValues();
355:                     this.currRightSubset = this.rightGroupedIterator.getValues();
356:                     this.matchStatus = MatchStatus.NONE_REMAINED;
357:                 } else if (0 < comp) {
358:                     // key1 goes first
359:                     this.currLeftSubset = this.leftGroupedIterator.getValues();
360:                     this.currRightSubset = Collections.singleton(null);
361:                     this.matchStatus = MatchStatus.SECOND_REMAINED;
362:                 } else {
363:                     // key 2 goes first
364:                     this.currLeftSubset = Collections.singleton(null);
365:                     this.currRightSubset = this.rightGroupedIterator.getValues();
366:                     this.matchStatus = MatchStatus.FIRST_REMAINED;
367:                 }
368:                 return true;
369:             }
370:         }
