70:         OPTIMIZER_CHOOSES,
71: 
72:         /** Use a sort-based strategy. */
73:         SORT,
74: 
75:         /**
76:          * Use a hash-based strategy. This should be faster in most cases, especially if the number
77:          * of different keys is small compared to the number of input elements (eg. 1/10).
78:          */
79:         HASH,
80: 
81:         /** Disable the use of a combiner. */
82:         NONE
