181:     public void setCustomPartitioner(Partitioner<?> customPartitioner) {
182:         if (customPartitioner != null) {
183:             int[] keys = getKeyColumns(0);
184:             if (keys == null || keys.length == 0) {
185:                 throw new IllegalArgumentException(
186:                         "Cannot use custom partitioner for a non-grouped GroupReduce (AllGroupReduce)");
187:             }
188:             if (keys.length > 1) {
189:                 throw new IllegalArgumentException(
190:                         "Cannot use the key partitioner for composite keys (more than one key field)");
191:             }
