202:     @Override
203:     protected List<T> executeOnCollections(
204:             List<T> inputData, RuntimeContext ctx, ExecutionConfig executionConfig)
205:             throws Exception {
206:         // make sure we can handle empty inputs
207:         if (inputData.isEmpty()) {
208:             return Collections.emptyList();
209:         }
210: 
211:         ReduceFunction<T> function = this.userFunction.getUserCodeObject();
212: 
213:         UnaryOperatorInformation<T, T> operatorInfo = getOperatorInfo();
214:         TypeInformation<T> inputType = operatorInfo.getInputType();
215: 
216:         int[] inputColumns = getKeyColumns(0);
217: 
218:         if (!(inputType instanceof CompositeType) && inputColumns.length > 1) {
219:             throw new InvalidProgramException("Grouping is only possible on composite types.");
220:         }
221: 
222:         FunctionUtils.setFunctionRuntimeContext(function, ctx);
223:         FunctionUtils.openFunction(function, DefaultOpenContext.INSTANCE);
224: 
225:         TypeSerializer<T> serializer =
226:                 getOperatorInfo().getInputType().createSerializer(executionConfig);
227: 
228:         if (inputColumns.length > 0) {
229:             boolean[] inputOrderings = new boolean[inputColumns.length];
230:             TypeComparator<T> inputComparator =
231:                     inputType instanceof AtomicType
232:                             ? ((AtomicType<T>) inputType).createComparator(false, executionConfig)
233:                             : ((CompositeType<T>) inputType)
234:                                     .createComparator(
235:                                             inputColumns, inputOrderings, 0, executionConfig);
236: 
237:             Map<TypeComparable<T>, T> aggregateMap =
238:                     new HashMap<TypeComparable<T>, T>(inputData.size() / 10);
239: 
240:             for (T next : inputData) {
241:                 TypeComparable<T> wrapper = new TypeComparable<T>(next, inputComparator);
242: 
243:                 T existing = aggregateMap.get(wrapper);
244:                 T result;
245: 
246:                 if (existing != null) {
247:                     result = function.reduce(existing, serializer.copy(next));
248:                 } else {
249:                     result = next;
250:                 }
251: 
252:                 result = serializer.copy(result);
253: 
254:                 aggregateMap.put(wrapper, result);
255:             }
256: 
257:             FunctionUtils.closeFunction(function);
258:             return new ArrayList<T>(aggregateMap.values());
259:         } else {
260:             T aggregate = inputData.get(0);
261: 
262:             aggregate = serializer.copy(aggregate);
263: 
264:             for (int i = 1; i < inputData.size(); i++) {
265:                 T next = function.reduce(aggregate, serializer.copy(inputData.get(i)));
266:                 aggregate = serializer.copy(next);
267:             }
268: 
269:             FunctionUtils.setFunctionRuntimeContext(function, ctx);
270: 
271:             return Collections.singletonList(aggregate);
272:         }
273:     }
