39: /** Utility class that contains helper methods for optimizer. */
40: public final class Utils {
41: 
42:     public static FieldList createOrderedFromSet(FieldSet set) {
43:         if (set instanceof FieldList) {
44:             return (FieldList) set;
45:         } else {
46:             final int[] cols = set.toArray();
47:             Arrays.sort(cols);
48:             return new FieldList(cols);
49:         }
50:     }
51: 
52:     public static Ordering createOrdering(FieldList fields, boolean[] directions) {
53:         final Ordering o = new Ordering();
54:         for (int i = 0; i < fields.size(); i++) {
55:             o.appendOrdering(
56:                     fields.get(i),
57:                     null,
58:                     directions == null || directions[i] ? Order.ASCENDING : Order.DESCENDING);
59:         }
60:         return o;
61:     }
62: 
63:     public static Ordering createOrdering(FieldList fields) {
64:         final Ordering o = new Ordering();
65:         for (int i = 0; i < fields.size(); i++) {
66:             o.appendOrdering(fields.get(i), null, Order.ANY);
67:         }
68:         return o;
69:     }
70: 
71:     public static boolean[] getDirections(Ordering o, int numFields) {
72:         final boolean[] dirs = o.getFieldSortDirections();
73:         if (dirs.length == numFields) {
74:             return dirs;
75:         } else if (dirs.length > numFields) {
76:             final boolean[] subSet = new boolean[numFields];
77:             System.arraycopy(dirs, 0, subSet, 0, numFields);
78:             return subSet;
79:         } else {
80:             throw new CompilerException();
81:         }
82:     }
