39: /** Utility class that contains helper methods for optimizer. */
40: public final class Utils {
41: 
42:     public static FieldList createOrderedFromSet(FieldSet set) {
43:         if (set instanceof FieldList) {
44:             return (FieldList) set;
45:         } else {
46:             final int[] cols = set.toArray();
47:             Arrays.sort(cols);
48:             return new FieldList(cols);
49:         }
50:     }
51: 
52:     public static Ordering createOrdering(FieldList fields, boolean[] directions) {
53:         final Ordering o = new Ordering();
54:         for (int i = 0; i < fields.size(); i++) {
55:             o.appendOrdering(
56:                     fields.get(i),
57:                     null,
58:                     directions == null || directions[i] ? Order.ASCENDING : Order.DESCENDING);
59:         }
60:         return o;
61:     }
62: 
63:     public static Ordering createOrdering(FieldList fields) {
64:         final Ordering o = new Ordering();
65:         for (int i = 0; i < fields.size(); i++) {
66:             o.appendOrdering(fields.get(i), null, Order.ANY);
67:         }
68:         return o;
69:     }
70: 
71:     public static boolean[] getDirections(Ordering o, int numFields) {
72:         final boolean[] dirs = o.getFieldSortDirections();
73:         if (dirs.length == numFields) {
74:             return dirs;
75:         } else if (dirs.length > numFields) {
76:             final boolean[] subSet = new boolean[numFields];
77:             System.arraycopy(dirs, 0, subSet, 0, numFields);
78:             return subSet;
79:         } else {
80:             throw new CompilerException();
81:         }
82:     }
83: 
84:     public static TypeComparatorFactory<?> getShipComparator(
85:             Channel channel, ExecutionConfig config) {
86:         PlanNode source = channel.getSource();
87:         Operator<?> javaOp = source.getProgramOperator();
88:         TypeInformation<?> type = javaOp.getOperatorInfo().getOutputType();
89:         return createComparator(
90:                 type,
91:                 channel.getShipStrategyKeys(),
92:                 getSortOrders(channel.getShipStrategyKeys(), channel.getShipStrategySortOrder()),
93:                 config);
94:     }
95: 
96:     private static <T> TypeComparatorFactory<?> createComparator(
97:             TypeInformation<T> typeInfo,
98:             FieldList keys,
99:             boolean[] sortOrder,
100:             ExecutionConfig executionConfig) {
101: 
102:         TypeComparator<T> comparator;
103:         if (typeInfo instanceof CompositeType) {
104:             comparator =
105:                     ((CompositeType<T>) typeInfo)
106:                             .createComparator(keys.toArray(), sortOrder, 0, executionConfig);
107:         } else if (typeInfo instanceof AtomicType) {
108:             // handle grouping of atomic types
109:             comparator = ((AtomicType<T>) typeInfo).createComparator(sortOrder[0], executionConfig);
110:         } else {
111:             throw new RuntimeException("Unrecognized type: " + typeInfo);
112:         }
113: 
114:         return new RuntimeComparatorFactory<>(comparator);
115:     }
116: 
117:     private static boolean[] getSortOrders(FieldList keys, boolean[] orders) {
118:         if (orders == null) {
119:             orders = new boolean[keys.size()];
120:             Arrays.fill(orders, true);
121:         }
122:         return orders;
123:     }
124: 
125:     // --------------------------------------------------------------------------------------------
126: 
127:     /** No instantiation. */
128:     private Utils() {
129:         throw new RuntimeException();
130:     }
131: }
