175:             TypeInformation<IN> typeInfo,
176:             int[] sortColumns,
177:             boolean[] sortOrderings,
178:             ExecutionConfig executionConfig) {
179:         if (typeInfo instanceof CompositeType) {
180:             return ((CompositeType<IN>) typeInfo)
181:                     .createComparator(sortColumns, sortOrderings, 0, executionConfig);
182:         } else if (typeInfo instanceof AtomicType) {
183:             return ((AtomicType<IN>) typeInfo).createComparator(sortOrderings[0], executionConfig);
