192:     @Override
193:     protected List<OUT> executeOnCollections(
194:             List<IN> inputData, RuntimeContext ctx, ExecutionConfig config)
195:             throws Exception {
196:         GroupReduceFunction<IN, OUT> function = this.userFunction.getUserCodeObject();
197: 
198:         UnaryOperatorInformation<IN, OUT> operatorInfo = getOperatorInfo();
199:         TypeInformation<IN> inputType = operatorInfo.getInputType();
200: 
201:         int[] keyColumns = getKeyColumns(0);
202:         int[] sortColumns = keyColumns;
203:         boolean[] sortOrderings = new boolean[sortColumns.length];
204: 
205:         if (groupOrder != null) {
206:             sortColumns = ArrayUtils.addAll(sortColumns, groupOrder.getFieldPositions());
207:             sortOrderings = ArrayUtils.addAll(sortOrderings, groupOrder.getFieldSortDirections());
208:         }
209: 
210:         if (sortColumns.length == 0) { // => all reduce. No comparator
211:             checkArgument(sortOrderings.length == 0);
212:         } else {
213:             final TypeComparator<IN> sortComparator =
214:                     getTypeComparator(inputType, sortColumns, sortOrderings, config);
215:             Collections.sort(
216:                     inputData,
217:                     new Comparator<IN>() {
218:                         @Override
219:                         public int compare(IN o1, IN o2) {
220:                             return sortComparator.compare(o1, o2);
221:                         }
222:                     });
223:         }
224: 
225:         FunctionUtils.setFunctionRuntimeContext(function, ctx);
226:         FunctionUtils.openFunction(function, DefaultOpenContext.INSTANCE);
227: 
228:         ArrayList<OUT> result = new ArrayList<OUT>();
229: 
230:         if (inputData.size() > 0) {
231:             final TypeSerializer<IN> inputSerializer = inputType.createSerializer(config);
232:             if (keyColumns.length == 0) {
233:                 TypeSerializer<OUT> outSerializer =
234:                         getOperatorInfo().getOutputType().createSerializer(config);
235:                 List<IN> inputDataCopy = new ArrayList<IN>(inputData.size());
236:                 for (IN in : inputData) {
237:                     inputDataCopy.add(inputSerializer.copy(in));
238:                 }
239:                 CopyingListCollector<OUT> collector =
240:                         new CopyingListCollector<OUT>(result, outSerializer);
241: 
242:                 function.reduce(inputDataCopy, collector);
243:             } else {
244:                 boolean[] keyOrderings = new boolean[keyColumns.length];
245:                 final TypeComparator<IN> comparator =
246:                         getTypeComparator(inputType, keyColumns, keyOrderings, config);
247: 
248:                 ListKeyGroupedIterator<IN> keyedIterator =
249:                         new ListKeyGroupedIterator<IN>(inputData, inputSerializer, comparator);
250: 
251:                 TypeSerializer<OUT> outSerializer =
252:                         getOperatorInfo().getOutputType().createSerializer(config);
253:                 CopyingListCollector<OUT> collector =
254:                         new CopyingListCollector<OUT>(result, outSerializer);
255: 
256:                 while (keyedIterator.nextKey()) {
257:                     function.reduce(keyedIterator.getValues(), collector);
258:                 }
259:             }
260:         }
261: 
262:         FunctionUtils.closeFunction(function);
263:         return result;
264:     }
